import React, { useState } from 'react';
import { StyleSheet, View } from 'react-native';
import { Button, SCREEN_HEIGHT, Text } from 'tradewize-component';
import { SvgXml } from 'react-native-svg';
import { colors } from '../../../../theme';
import { IconArrowDown2 } from '../../../../assets/svg';
import { useAppTranslation } from '../../../../hooks/useAppTranslation';
import { useSelector } from 'react-redux';
import { RootState } from '../../../../../../Auth/src/redux/store/types';
import ChatContainer from '../../../../components/ChatContainer';

interface JobChatGroupProps {
  onFocusInput?: () => void;
}

const JobChatGroup = ({ onFocusInput }: JobChatGroupProps) => {
  const { t } = useAppTranslation();
  const [isExpanded, setIsExpanded] = useState(true);

  const chatGroup = useSelector(
    (state: RootState) => state.jobDetail.chatGroup.data,
  );
  const isLoadingJobDetail = useSelector(
    (state: RootState) => state.jobDetail.workOrder?.isLoading,
  );

  return (
    <View style={styles.container}>
      <Button
        variant="ghost"
        style={styles.header}
        onPress={() => {
          setIsExpanded(!isExpanded);
        }}
        activeOpacity={0.7}
      >
        <Text style={styles.headerText}>{t('JOB_CHAT_GROUP')}</Text>
        <SvgXml
          xml={IconArrowDown2(colors.black)}
          width={16}
          height={16}
          style={isExpanded ? styles.iconTransform : {}}
        />
      </Button>

      {isExpanded && (
        <View style={styles.content}>
          <ChatContainer
            isLoading={isLoadingJobDetail}
            onFocusInput={onFocusInput}
            isKeyboardInternallyHandled={false}
            chatId={chatGroup?.id || ''}
            useScrollView={true}
            giftedChatProps={{
              inverted: false,
            }}
          />
        </View>
      )}
    </View>
  );
};

const styles = StyleSheet.create({
  container: {
    backgroundColor: colors.white,
    borderRadius: 8,
    borderWidth: 1,
    borderColor: colors.grayScale30,
    marginBottom: 16,
  },
  header: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    padding: 16,
  },
  headerText: {
    fontSize: 16,
    fontWeight: '600',
    color: colors.black,
  },
  content: {
    height: SCREEN_HEIGHT * 0.4,
    paddingTop: 0,
    paddingBottom: 8,
  },
  iconTransform: {
    transform: [{ rotate: '180deg' }],
  },
});

export default JobChatGroup;
