import React, {
  useState,
  useMemo,
  useEffect,
  useCallback,
} from 'react';
import {
  View,
  ScrollView,
  TouchableOpacity,
  ActivityIndicator,
  Dimensions,
} from 'react-native';
import dayjs from 'dayjs';
import { SvgXml } from 'react-native-svg';
import Orientation, { OrientationType } from 'react-native-orientation-locker';
import { Calendar } from 'react-native-big-calendar';
import { useFocusEffect } from '@react-navigation/native';
import { colors } from '../../theme';
import {
  IconChevronLeft,
  IconChevronRight,
} from '../../assets/svg';
import { BaseContainer, HeaderBase, SCREEN_HEIGHT, SCREEN_WIDTH, Text } from 'tradewize-component';
import { useDispatch, useSelector } from 'react-redux';
import { useAppTranslation } from '../../hooks/useAppTranslation';
import { NavigationService } from '../../services/NavigationService';
import { styles } from './styles';

type ViewMode = 'week' | 'month';

const JobBoardCalendarScreen = () => {
  const dispatch = useDispatch();
  const { t } = useAppTranslation();
  const [selectedDate, setSelectedDate] = useState(new Date());
  const [viewMode, setViewMode] = useState<ViewMode>('week');
  const [isViewModeLoading, setIsViewModeLoading] = useState(false);
  const [isLandscape, setIsLandscape] = useState(false);
  
  const allJobs = useSelector(
    (state: any) => state.jobBoard.houseHasJobWorker.data || [],
  );

  const events = useMemo(() => {
    return allJobs.filter((job: any) => job.estStartDate && job.estEndDate).map((job: any) => ({
      id: job.jobId,
      title: `${job.activityTypeName?.trim() || ''} - ${job.companyRoleName?.trim() || ''}`,
      start: new Date(job.estStartDate),
      end: new Date(job.estEndDate),
      originalData: job,
    }));
  }, [allJobs]);

  const today = new Date();

  useFocusEffect(
    useCallback(() => {
      Orientation.unlockAllOrientations();
      const onDevice = (device: OrientationType) => {
        handleOrientationChange?.(device);
      };

      Orientation.addDeviceOrientationListener(onDevice);
      return () => {
        Orientation.lockToPortrait();
        setIsLandscape(false);
        Orientation.removeOrientationListener(handleOrientationChange);
      };
      // eslint-disable-next-line react-hooks/exhaustive-deps
    }, []),
  );

  const handleOrientationChange = (orientation: OrientationType) => {
    if (viewMode === 'month') {
      setIsLandscape(false);
    } else {
      setIsLandscape(
        orientation === 'LANDSCAPE-RIGHT' ||
          orientation === 'LANDSCAPE-LEFT' ||
          orientation === 'UNKNOWN' ||
          orientation === 'PORTRAIT-UPSIDEDOWN',
      );
    }
  };

  useEffect(() => {
    const handleOrientationChange = () => {
      if (viewMode === 'month') {
        setIsLandscape(false);
      } else {
        setIsLandscape(SCREEN_WIDTH > SCREEN_HEIGHT);
      }
    };
    handleOrientationChange();
    const subscription = Dimensions.addEventListener(
      'change',
      handleOrientationChange,
    );

    return () => {
      subscription?.remove();
    };
  }, [viewMode]);

  useEffect(() => {
    if (viewMode === 'month') {
      setIsLandscape(false);
    }
  }, [viewMode]);

  const weekDays = useMemo(() => {
    if (viewMode === 'week') {
      const start = dayjs(selectedDate).startOf('week').add(1, 'day');
      return Array.from({ length: 7 }, (_, i) => start.add(i, 'day').toDate());
    } else {
      const start = dayjs(selectedDate).startOf('month');
      const end = dayjs(selectedDate).endOf('month');
      const daysInMonth = end.diff(start, 'day') + 1;
      return Array.from({ length: daysInMonth }, (_, i) =>
        start.add(i, 'day').toDate(),
      );
    }
  }, [selectedDate, viewMode]);

  const eventsInCurrentPeriod = useMemo(() => {
    const periodStart = dayjs(weekDays[0]).startOf('day');
    const periodEnd = dayjs(weekDays[weekDays.length - 1]).endOf('day');

    return events.filter((event: any) => {
      const startDateObj = dayjs(event.start);
      const endDateObj = dayjs(event.end);
      return (
        startDateObj.isBefore(periodEnd) && endDateObj.isAfter(periodStart)
      );
    });
  }, [events, weekDays]);

  const getEventPosition = (event: any) => {
    const startDateObj = dayjs(event.start);
    const endDateObj = dayjs(event.end);
    const periodStart = dayjs(weekDays[0]);

    const startDay = startDateObj.diff(periodStart, 'day');
    const endDay = endDateObj.diff(periodStart, 'day');
    const maxDays = weekDays.length - 1;

    return {
      startDay: Math.max(0, startDay),
      endDay: Math.min(maxDays, endDay),
    };
  };

  const navigatePeriod = (direction: 'prev' | 'next') => {
    const newDate =
      direction === 'prev'
        ? dayjs(selectedDate).subtract(1, viewMode)
        : dayjs(selectedDate).add(1, viewMode);
    setSelectedDate(newDate.toDate());
  };

  const handleViewModeChange = (newViewMode: ViewMode) => {
    if (newViewMode !== viewMode) {
      setIsViewModeLoading(true);
      setViewMode(newViewMode);
      setTimeout(() => {
        setIsViewModeLoading(false);
      }, 500);
    }
  };

  const getHeaderTitle = () => {
    if (viewMode === 'week') {
      return `${dayjs(weekDays[0]).format('MMM DD')} - ${dayjs(
        weekDays[6],
      ).format('MMM DD, YYYY')}`;
    } else {
      return dayjs(selectedDate).format('MMMM YYYY');
    }
  };

  const getDayWidth = () => {
    return isLandscape ? 120 : 180;
  };

  const getColor = (job: any) => {
    if (job?.isChecked) {
      return colors.mainColorPrimary;
    }
    if (job?.isOverlap || job?.isDiffDays) {
      return colors.colorE0E0E0;
    }
    return colors.twColors.background.lot;
  };
  
  const handleToggleJob = async (job: any) => {
    const redux = await import('auth/redux');
    if (job?.isOverlap) {
      return dispatch(
        redux.actionContainer.showAlertAsync({
          title: t('WARNING'),
          message: t('THIS_JOB_OVERLAPS_WITH_ANOTHER_JOB_IN_YOUR_SCHEDULE'),
          titleStyle: { color: colors.black },
          type: 'warning',
          buttonText: t('CONFIRM'),
        }),
      );
    }
    if (job?.isDiffDays) {
      return dispatch(
        redux.actionContainer.showAlertAsync({
          title: t('WARNING'),
          message: t('CANNOT_REGISTER_FOR_JOBS_STARTING_MORE_THAN_14_DAYS_FROM_NOW'),
          titleStyle: { color: colors.black },
          buttonText: t('CONFIRM'),
        }),
      );
    }
    if (job?.isDisabled) {
      return dispatch(
        redux.actionContainer.showAlertAsync({
          title: t('WARNING'),
          message: t('CANNOT_REGISTER_MORE_THAN_ONE_JOB_IN_THE_SAME_HOUSE'),
          titleStyle: { color: colors.black },
          buttonText: t('CONFIRM'),
        }),
      );
    }
    dispatch(redux.actionContainer.toggleJobBoardCheckbox(job?.jobId));
  };


  return (
    <BaseContainer>
      <HeaderBase
        title={t('CALENDAR')}
        onPressBack={() => NavigationService.goBack()}
      />
      <View style={styles.container}>
        <View
          style={[styles.viewModeContainer, styles.viewModeContainerLandscape, { marginTop: 16 }]}
        >
          <TouchableOpacity
            style={[
              styles.viewModeButton,
              viewMode === 'week' && styles.activeViewModeButton,
            ]}
            onPress={() => handleViewModeChange('week')}
            disabled={isViewModeLoading}
          >
            <Text
              style={[
                styles.viewModeText,
                viewMode === 'week' && styles.activeViewModeText,
              ]}
            >
              {t('WEEK')}
            </Text>
          </TouchableOpacity>
          <TouchableOpacity
            style={[
              styles.viewModeButton,
              viewMode === 'month' && styles.activeViewModeButton,
            ]}
            onPress={() => handleViewModeChange('month')}
            disabled={isViewModeLoading}
          >
            <Text
              style={[
                styles.viewModeText,
                viewMode === 'month' && styles.activeViewModeText,
              ]}
            >
              {t('MONTH')}
            </Text>
          </TouchableOpacity>
        </View>

        {viewMode === 'week' && (
          <View style={[styles.header, styles.headerLandscape, { position: 'relative' }]}>
            <TouchableOpacity
              onPress={() => navigatePeriod('prev')}
              style={[styles.navButton, styles.navButtonLandscape]}
            >
              <SvgXml
                xml={IconChevronLeft(colors.black)}
                width={20}
                height={20}
              />
            </TouchableOpacity>
            <Text style={[styles.headerTitle, styles.headerTitleLandscape]}>
              {getHeaderTitle()}
            </Text>
            <View style={styles.headerRight}>
              <TouchableOpacity
                onPress={() => navigatePeriod('next')}
                style={[styles.navButton, styles.navButtonLandscape]}
              >
                <SvgXml
                  xml={IconChevronRight(colors.black)}
                  width={20}
                  height={20}
                />
              </TouchableOpacity>
            </View>
          </View>
        )}

        {isViewModeLoading && (
          <View style={styles.loadingOverlay}>
            <View style={styles.loadingContainer}>
              <ActivityIndicator size="large" color={colors.mainColorPrimary} />
            </View>
          </View>
        )}

        {viewMode === 'month' ? (
          <View style={styles.calendarContainer}>
            <View style={styles.monthYearHeader}>
              <TouchableOpacity
                onPress={() => navigatePeriod('prev')}
                style={styles.monthNavButton}
              >
                <SvgXml
                  xml={IconChevronLeft(colors.black)}
                  width={20}
                  height={20}
                />
              </TouchableOpacity>
              <Text style={styles.monthYearTitle}>
                {dayjs(selectedDate).format('MMMM YYYY')}
              </Text>
              <TouchableOpacity
                onPress={() => navigatePeriod('next')}
                style={styles.monthNavButton}
              >
                <SvgXml
                  xml={IconChevronRight(colors.black)}
                  width={20}
                  height={20}
                />
              </TouchableOpacity>
            </View>
            <Calendar
              date={
                new Date(selectedDate.getFullYear(), selectedDate.getMonth(), 1)
              }
              key={`${selectedDate.getFullYear()}-${selectedDate.getMonth()}`}
              events={eventsInCurrentPeriod}
              height={500}
              mode="month"
              maxVisibleEventCount={2}
              moreLabel="..."
              swipeEnabled={false}
              eventCellStyle={(evt: any) => ({
                backgroundColor: getColor(evt.originalData),
                borderRadius: 6,
              })}
              renderEvent={(event: any, touchableOpacityProps: any) => {
                const { key, ...restProps } = touchableOpacityProps;
                const jobColor = getColor(event.originalData);
                const txtColor = event.originalData.isChecked ? colors.white : colors.black;
                return (
                  <TouchableOpacity
                    {...restProps}
                    style={[
                      touchableOpacityProps.style,
                      {
                        backgroundColor: jobColor,
                        borderRadius: 6,
                        padding: 2,
                        justifyContent: 'center',
                        alignItems: 'center',
                      },
                    ]}
                  >
                    <Text
                      numberOfLines={1}
                      style={{
                        color: txtColor,
                        fontSize: 10,
                        fontWeight: '600',
                        textAlign: 'center',
                      }}
                    >
                      Lot:{event.originalData?.lotNumber || ''} - {event.title}
                    </Text>
                  </TouchableOpacity>
                );
              }}
              onPressEvent={(event: any) => {
                 handleToggleJob(event.originalData);
              }}
              onPressCell={(date: any) => {
              }}
            />
          </View>
        ) : (
          <View style={[styles.ganttContainer, styles.ganttContainerLandscape]}>
            <ScrollView
              horizontal
              showsHorizontalScrollIndicator={true}
              nestedScrollEnabled={true}
              contentContainerStyle={{
                minWidth: weekDays.length * getDayWidth(),
              }}
              indicatorStyle="black"
              style={{ flex: 1 }}
            >
              <View style={[styles.scrollContent, styles.scrollContentLandscape]}>
                <View style={styles.dayHeaders}>
                  {weekDays.map((day, index) => {
                    const isToday = dayjs(day).isSame(today, 'day');
                    const isWeekend =
                      dayjs(day).day() === 0 || dayjs(day).day() === 6;
                    const dayWidth = getDayWidth();
                    return (
                      <View
                        key={index}
                        style={[
                          styles.dayHeader,
                          { width: dayWidth },
                          isToday && styles.selectedDayHeader,
                          isWeekend && styles.weekendHeader,
                          styles.dayHeaderLandscape,
                        ]}
                      >
                        <Text
                          style={[
                            styles.dayHeaderText,
                            isToday && styles.selectedDayHeaderText,
                            isWeekend && styles.weekendHeaderText,
                          ]}
                        >
                          {dayjs(day).format('ddd MMM DD, YYYY')}
                        </Text>
                      </View>
                    );
                  })}
                </View>
                <ScrollView
                  style={[
                    styles.ganttContentColumn,
                    styles.ganttContentColumnLandscape,
                  ]}
                  showsVerticalScrollIndicator={true}
                  nestedScrollEnabled={true}
                  contentContainerStyle={{
                    paddingBottom: 20,
                    minWidth: '100%',
                    minHeight: eventsInCurrentPeriod.length * 50 + 40,
                  }}
                >
                  {eventsInCurrentPeriod.map((event: any, eventIndex: number) => {
                    const position = getEventPosition(event);
                    const isShow = position.endDay - position.startDay + 1 > 0;

                    const dayWidth = getDayWidth();
                    const barMarginLeft = Math.max(
                      0,
                      position.startDay * dayWidth,
                    );
                    const barWidth = !isShow
                      ? 0
                      : Math.max(
                          30,
                          (position.endDay - position.startDay + 1) * dayWidth,
                        );
                    const jobColor = getColor(event.originalData);
                    const txtColor = event.originalData.isChecked ? colors.white : colors.black;

                    return (
                      <View
                        key={eventIndex}
                        style={{
                          position: 'relative',
                          height: 50,
                          justifyContent: 'center',
                          minWidth: weekDays.length * dayWidth,
                          marginBottom: 2,
                        }}
                      >
                        <View
                          style={{
                            flexDirection: 'row',
                            minWidth: weekDays.length * dayWidth,
                          }}
                        >
                          {weekDays.map((_, dayIdx) => (
                            <View
                              key={dayIdx}
                              style={{
                                width: dayWidth,
                                height: 40,
                                borderRightWidth: 1,
                                borderColor: '#eee',
                                backgroundColor: '#fff',
                              }}
                            />
                          ))}
                        </View>
                        <TouchableOpacity
                          activeOpacity={0.7}
                          onPress={() => {
                            handleToggleJob(event.originalData);
                          }}
                          style={{
                            position: 'absolute',
                            left: barMarginLeft,
                            top: 7,
                            height: 36,
                            width: barWidth,
                            backgroundColor: jobColor,
                            borderRadius: 8,
                            justifyContent: 'center',
                            paddingHorizontal: !isShow ? 0 : 8,
                            zIndex: 2,
                            elevation: 2,
                            borderWidth: 1,
                            borderColor: colors.grayScale40,
                          }}
                        >
                          <Text
                            style={{
                              color: txtColor,
                              fontWeight: 'bold',
                              fontSize: 12,
                            }}
                            numberOfLines={1}
                          >
                            {`Lot: ${event.originalData.lotNumber || ''} - ${event.title}`}
                          </Text>
                        </TouchableOpacity>
                      </View>
                    );
                  })}
                </ScrollView>
              </View>
            </ScrollView>
          </View>
        )}
      </View>
    </BaseContainer>
  );
};
export default JobBoardCalendarScreen;
