import React, { useState } from 'react';
import { View } from 'react-native';
import { styles } from './styles';
import { Button, SCREEN_WIDTH, Text } from 'tradewize-component';
import { useAppTranslation } from '../../../../hooks/useAppTranslation';
import { SvgXml } from 'react-native-svg';
import { IconChevronDown, IconChevronRight } from '../../../../assets/svg';
import { colors } from '../../../../theme';
import { WARRANTY_STATUS } from '../../types';

interface Props {
  community: string;
  address: string;
  lotNumber: string;
  estStartDate: string;
  status: number;
}

const getStatusColor = (warrantyStatus: number) => {
  if (warrantyStatus === WARRANTY_STATUS.WAITING_ACCEPT) {
    return colors.mainColorPrimary;
  }
  if (warrantyStatus === WARRANTY_STATUS.ACCEPTED) {
    return colors.alertColorSuccess;
  }
  return colors.orange;
};

const Detail = ({
  community,
  address,
  lotNumber,
  estStartDate,
  status,
}: Props) => {
  const { t } = useAppTranslation();

  const [isExpanded, setIsExpanded] = useState(true);

  return (
    <View style={styles.container}>
      <View style={styles.header}>
        <Text style={styles.title}>{t('WARRANTY_DETAIL')}</Text>
        <Button
          variant="ghost"
          style={styles.btnExpand}
          onPress={() => setIsExpanded(!isExpanded)}
        >
          <SvgXml
            xml={
              isExpanded
                ? IconChevronDown(colors.black)
                : IconChevronRight(colors.black)
            }
            width={SCREEN_WIDTH * 0.06}
            height={SCREEN_WIDTH * 0.06}
          />
        </Button>
      </View>
      {isExpanded && <View style={styles.line} />}
      {isExpanded && (
        <View style={styles.content}>
          <View style={styles.row}>
            <Text style={styles.label}>{t('COMMUNITY')}</Text>
            <View style={styles.valueWrapper}>
              <Text style={styles.value}>{community}</Text>
            </View>
          </View>
          <View style={styles.row}>
            <Text style={styles.label}>{t('ADDRESS')}</Text>
            <View style={styles.valueWrapper}>
              <Text style={styles.value}>{address}</Text>
            </View>
          </View>
          <View style={styles.row}>
            <Text style={styles.label}>{t('LOT_NUMBER')}</Text>
            <View style={styles.valueWrapper}>
              <Text style={styles.value}>{lotNumber}</Text>
            </View>
          </View>
          <View style={styles.row}>
            <Text style={styles.label}>{t('EST_START_DATE')}</Text>
            <View style={styles.valueWrapper}>
              <Text style={styles.value}>{estStartDate}</Text>
            </View>
          </View>
          <View style={styles.row}>
            <Text style={styles.label}>{t('STATUS')}</Text>
            <View style={styles.valueWrapper}>
              <Text style={[styles.value, { color: getStatusColor(status) }]}>
                {status}
              </Text>
            </View>
          </View>
        </View>
      )}
    </View>
  );
};

export default Detail;
