import React, {
  useState,
  useCallback,
  useRef,
  useMemo,
  forwardRef,
  useImperativeHandle,
} from 'react';
import { View, TextInput } from 'react-native';
import BottomSheet, {
  BottomSheetBackdrop,
  BottomSheetBackdropProps,
  BottomSheetScrollView,
} from '@gorhom/bottom-sheet';
import { Text, Button } from 'tradewize-component';
import { Dropdown } from 'react-native-element-dropdown';
import { useAppTranslation } from '../../../../hooks/useAppTranslation';
import { styles } from './styles';
import { useSafeAreaInsets } from 'react-native-safe-area-context';
import { colors } from '../../../../theme';
import { SvgXml } from 'react-native-svg';
import { IconCalendar } from '../../../../assets/svg';
import { formatDate } from '../../../../utils';
import dayjs from 'dayjs';

interface CommunityItem {
  id: string;
  name: string;
}

export interface FilterModalRef {
  open: () => void;
  close: () => void;
}

interface FilterModalProps {
  communities: CommunityItem[];
  initialFilter: {
    CommunityId?: string;
    LotNumber?: string;
  };
  onApply: (filter: {
    CommunityId?: string;
    LotNumber?: string;
    StartDate?: string;
    EndDate?: string;
  }) => void;
  onReset: () => void;
  onClose: () => void;
  setIsFocusedCalendar: (value: boolean) => void;
  rangeDate: { startDate: string; endDate: string };
  setRangeDate: (range: { startDate: string; endDate: string }) => void;
}

const FilterModal = forwardRef<FilterModalRef, FilterModalProps>(
  (
    {
      communities,
      initialFilter,
      onApply,
      onReset,
      onClose,
      setIsFocusedCalendar,
      rangeDate,
      setRangeDate,
    },
    ref,
  ) => {
    const { t } = useAppTranslation();
    const insets = useSafeAreaInsets();
    const bottomSheetRef = useRef<BottomSheet>(null);
    const snapPoints = useMemo(() => ['85%'], []);

    const [tempLotNumber, setTempLotNumber] = useState(
      initialFilter.LotNumber || '',
    );
    const [selectedCommunityId, setSelectedCommunityId] = useState<
      string | null
    >(initialFilter.CommunityId || null);

    useImperativeHandle(ref, () => ({
      open: () => {
        bottomSheetRef.current?.snapToIndex(0);
      },
      close: () => {
        bottomSheetRef.current?.close();
      },
    }));

    const communityOptions = communities.map(c => ({
      value: c.id,
      label: c.name,
    }));

    const handleApply = useCallback(() => {
      const newFilters: {
        CommunityId?: string;
        LotNumber?: string;
        StartDate?: string;
        EndDate?: string;
      } = {};

      if (selectedCommunityId) {
        newFilters.CommunityId = selectedCommunityId;
      }
      if (tempLotNumber.trim()) {
        newFilters.LotNumber = tempLotNumber.trim();
      }
      if (rangeDate?.startDate && rangeDate?.endDate) {
        newFilters.StartDate = dayjs(rangeDate.startDate).format('YYYY-MM-DD');
        newFilters.EndDate = dayjs(rangeDate.endDate).format('YYYY-MM-DD');
      }

      onApply(newFilters);
      bottomSheetRef.current?.close();
    }, [selectedCommunityId, tempLotNumber, rangeDate, onApply]);

    const handleReset = useCallback(() => {
      setTempLotNumber('');
      setRangeDate({ startDate: '', endDate: '' });
      setSelectedCommunityId(null);
      onReset();
      bottomSheetRef.current?.close();
    }, [onReset]);

    const handleSheetClose = useCallback(() => {
      onClose();
    }, [onClose]);

    const renderBackdrop = useCallback(
      (props: BottomSheetBackdropProps) => (
        <BottomSheetBackdrop
          {...props}
          disappearsOnIndex={-1}
          appearsOnIndex={0}
          opacity={0.5}
          pressBehavior="close"
        />
      ),
      [],
    );

    return (
      <BottomSheet
        ref={bottomSheetRef}
        index={-1}
        snapPoints={snapPoints}
        animateOnMount={true}
        enablePanDownToClose={true}
        enableContentPanningGesture={true}
        enableHandlePanningGesture={true}
        enableDynamicSizing={false}
        keyboardBehavior="interactive"
        keyboardBlurBehavior="restore"
        style={styles.bottomSheet}
        backdropComponent={renderBackdrop}
        onClose={handleSheetClose}
      >
        <BottomSheetScrollView
          style={styles.bottomSheetContent}
          contentContainerStyle={styles.scrollContent}
          showsVerticalScrollIndicator={false}
          bounces={false}
        >
          {/* Community Selector */}
          <View style={styles.selectorContainer}>
            <Text style={styles.selectorLabel}>{t('COMMUNITY')}</Text>
            <Dropdown
              style={styles.dropdown}
              placeholderStyle={styles.dropdownPlaceholder}
              selectedTextStyle={styles.dropdownSelectedText}
              data={communityOptions}
              labelField="label"
              valueField="value"
              placeholder={t('SELECT_COMMUNITY')}
              value={selectedCommunityId}
              onChange={item => setSelectedCommunityId(item.value)}
            />
          </View>

          {/* Lot Number */}
          <Text style={styles.label}>{t('LOT_NUMBER')}</Text>
          <TextInput
            value={tempLotNumber}
            onChangeText={setTempLotNumber}
            placeholder={t('ENTER_LOT_NO')}
            keyboardType="number-pad"
            style={[styles.textInput, styles.inputOverlayButton]}
            placeholderTextColor={colors.color999999}
          />

          {/* Start Date */}
          <Text style={styles.label}>{t('START_DATE')}</Text>
          <Button
            onPress={() => setIsFocusedCalendar(true)}
            variant="ghost"
            style={styles.btnTextInput}
          >
            <TextInput
              editable={false}
              value={
                rangeDate.startDate && rangeDate.endDate
                  ? `${formatDate(rangeDate.startDate)} - ${formatDate(
                      rangeDate.endDate,
                    )}`
                  : ''
              }
              placeholder="YYYY-MM-DD"
              style={[styles.textInput, styles.inputBtn]}
            />
            <SvgXml
              xml={IconCalendar(colors.color999999)}
              width={24}
              height={24}
            />
          </Button>
        </BottomSheetScrollView>

        {/* Action Buttons - Fixed at Bottom */}
        <View
          style={[styles.filterFooter, { paddingBottom: insets.bottom || 24 }]}
        >
          <Button style={styles.resetButton} onPress={handleReset}>
            <Text style={styles.resetButtonText}>{t('RESET')}</Text>
          </Button>
          <Button style={styles.applyButton} onPress={handleApply}>
            <Text style={styles.applyButtonText}>{t('APPLY')}</Text>
          </Button>
        </View>
      </BottomSheet>
    );
  },
);

FilterModal.displayName = 'FilterModal';

export default FilterModal;
