import { useCallback, useEffect, useMemo, useState } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { useRoute } from '@react-navigation/native';
import { NavigationService } from '../../services/NavigationService';
import { RootState } from '../../../../Auth/src/redux/store/types';
import {
  getQIInspectionDataAsync,
  toggleQIInspectionCheck,
  requestReinspectAsync,
  clearQIInspection,
} from '../../../../Auth/src/redux/features/jobDetail/actions';
import { SCREEN_ENUM } from '../../types/global';
import { qIStatus } from '../../types/jobDetail.type';
import { useAppTranslation } from '../../hooks/useAppTranslation';
import { isPassValidateFilesByFileSetting } from '../../helper/checkList.helper';
import {
  showAlertAsync,
  hideAlertAsync,
} from '../../../../Auth/src/redux/features/app/actions';
import {
  showConfirmModal,
  hideConfirmModal,
} from '../../../../Auth/src/redux/features/app/actions';
import { actionContainer } from '../../../../Auth/src/redux';

export interface QIInspectionRouteParams {
  taskId: string;
  isInspector: boolean;
  qiIncompleteItems: number;
}

const useQIInspection = () => {
  const dispatch = useDispatch();
  const route: any = useRoute();
  const { t } = useAppTranslation();
  const { taskId, qiIncompleteItems } = route.params as QIInspectionRouteParams;

  const QI_SCREEN_KEY = SCREEN_ENUM.QIInspectionScreen;

  // QI metadata from saga (stored separately from keyed checklist)
  const [qiStatusName, setQiStatusName] = useState('');
  const [canRequestReInspect, setCanRequestReInspect] = useState(false);

  // Select checklist data from keyed state
  const checklists = useSelector(
    (state: RootState) =>
      state.jobDetail?.checklists?.[QI_SCREEN_KEY]?.data ?? [],
  );
  const isLoading = useSelector(
    (state: RootState) =>
      state.jobDetail?.checklists?.[QI_SCREEN_KEY]?.isLoading ?? false,
  );

  // Clear stale state + Fetch fresh data on mount
  // Clear on unmount to prevent stale checked state persisting in Redux
  useEffect(() => {
    // Clear any stale state from previous visit FIRST
    dispatch(clearQIInspection());

    if (taskId) {
      dispatch(getQIInspectionDataAsync({ scheduleId: taskId }));
    }

    return () => {
      // Cleanup on unmount (Back, navigate away)
      dispatch(clearQIInspection());
    };
  }, [dispatch, taskId]);

  // Listen for data to derive QI metadata
  // (qiStatusName + canRequestReInspect from saga-transformed items)
  useEffect(() => {
    if (checklists.length > 0) {
      const firstItem = checklists[0] as any;
      const qiStatus = firstItem?.qiStatus;

      // Map qiStatus to display name (matches original getStatusQI)
      const statusNameMap: { [key: number]: string } = {
        [qIStatus.Pending]: t('PENDING'),
        [qIStatus.WaitingForFixes]: t('INCOMPLETE_ITEMS'),
        [qIStatus.WaitingReinspect]: t('WAITING_REINSPECT'),
        [qIStatus.Completed]: t('COMPLETED'),
      };
      setQiStatusName(statusNameMap[qiStatus] || '');

      // canRequestReInspect comes from API response (set by saga)
      setCanRequestReInspect(firstItem?.canRequestReInspect ?? false);
    }
  }, [checklists, t]);

  /**
   * Handle checkbox press for QI Inspection item.
   * LOCAL ONLY — no API call. Validates file requirements first.
   */
  const handleCheckItem = useCallback(
    (item: any) => {
      // Skip if checkbox is hidden
      if (item.hideCheckBox) {
        return;
      }

      // Validate: require comment + photo/video before allowing check
      if (!isPassValidateFilesByFileSetting(item, null)) {
        dispatch(
          showAlertAsync({
            visible: true,
            title: t('WARNING'),
            message: t(
              'YOU_NEED_UPLOAD_AT_LEAST_ONE_PICTURE_TO_COMPLETE_THIS_CHECKLIST',
            ),
            type: 'warning',
            buttonText: t('OK'),
            onClose: () => {
              dispatch(hideAlertAsync());
              // Open comment modal for this item
              dispatch(
                actionContainer.showCommentChecklistModal({
                  item: {
                    ...item,
                    screenKey: QI_SCREEN_KEY,
                  },
                  visible: true,
                }),
              );
            },
          }),
        );
        return;
      }

      // LOCAL toggle only — no API call
      dispatch(toggleQIInspectionCheck({ itemId: item.id }));
    },
    [dispatch, t, QI_SCREEN_KEY],
  );

  /**
   * Handle comment press — open CommentChecklist modal
   */
  const handleCommentPress = useCallback(
    (item: any) => {
      dispatch(
        actionContainer.showCommentChecklistModal({
          item: {
            ...item,
            screenKey: QI_SCREEN_KEY,
          },
          visible: true,
        }),
      );
    },
    [dispatch, QI_SCREEN_KEY],
  );

  /**
   * Handle Request Reinspect.
   * If all items checked → confirm → call API + goBack.
   * If not all checked → show warning.
   */
  const handleRequestReinspect = useCallback(() => {
    const allChecked =
      checklists.length > 0 &&
      checklists.every((item: any) => item.isChecked === true);

    if (!allChecked) {
      // Warning: need to check all items first
      dispatch(
        showAlertAsync({
          visible: true,
          title: t('WARNING'),
          message: t('PLEASE_CHECK_ALL_ITEMS'),
          type: 'warning',
          buttonText: t('OK'),
          onClose: () => {
            dispatch(hideAlertAsync());
          },
        }),
      );
      return;
    }

    // Confirm → call API
    dispatch(
      showConfirmModal({
        title: t('CONFIRM'),
        description: t('REQUEST_REINSPECT_QI_FORM'),
        confirmText: t('OK'),
        cancelText: t('CANCEL'),
        onConfirm: () => {
          dispatch(hideConfirmModal());
          dispatch(
            requestReinspectAsync({
              scheduleActivityId: taskId,
              onSuccess: () => {
                NavigationService.goBack();
              },
            }),
          );
        },
        onCancel: () => {
          dispatch(hideConfirmModal());
        },
      }),
    );
  }, [dispatch, t, taskId, checklists]);

  // Count checked items for progress display
  const checkedCount = useMemo(
    () => checklists.filter((item: any) => item.isChecked).length,
    [checklists],
  );

  // Are all items checked?
  const isChecklistCompleted = useMemo(
    () =>
      checklists.length > 0 &&
      checklists.every((item: any) => item.isChecked === true),
    [checklists],
  );

  return {
    checklists,
    isLoading,
    taskId,
    qiIncompleteItems,
    qiStatusName,
    canRequestReInspect,
    handleCheckItem,
    handleCommentPress,
    handleRequestReinspect,
    checkedCount,
    isChecklistCompleted,
    QI_SCREEN_KEY,
  };
};

export default useQIInspection;
