import React, { useCallback, useEffect, useState } from 'react';
import { ScrollView, View } from 'react-native';
import { styles } from './styles';
import { BaseContainer, Button, HeaderBase, Text } from 'tradewize-component';
import { useAppTranslation } from '../../hooks/useAppTranslation';
import { NavigationService } from '../../services/NavigationService';
import { useDispatch, useSelector } from 'react-redux';
import { logger } from '../../utils';
import { useRoute } from '@react-navigation/native';
import Detail from './components/Detail';
import Description from './components/Description';
import Response from './components/Response';
import dayjs from 'dayjs';
import Comment from './components/Comment';
import { WARRANTY_STATUS } from './types';

const WarrantyJobDetail = () => {
  const route = useRoute();
  const params = route?.params as { id: string; scheduleActivityId: string };
  const dispatch = useDispatch();
  const { t } = useAppTranslation();

  const jobsWarranty = useSelector(
    (state: any) => state.myjob.myJobsWarranty.data,
  );
  const isLoading = useSelector(
    (state: any) => state.myjob.myJobsWarranty.isLoading,
  );
  const isLoadingSubmitWarranty = useSelector(
    (state: any) => state.myjob.submitWarranty.isLoading,
  );
  const materialsWarranty = useSelector(
    (state: any) => state.myjob.materialsWarranty?.data,
  );

  const [date, setDate] = useState('');
  const [correctionNeeded, setCorrectionNeeded] = useState('');

  const fetchJobWarrantyDetail = useCallback(async () => {
    try {
      const redux = await import('auth/redux');
      dispatch(redux.actionContainer.getMyJobsWarrantyAsync(params?.id));
    } catch (error) {
      logger();
    }
  }, [params?.id]);

  const handleSubmitWarranty = async () => {
    const redux = await import('auth/redux');

    try {
      if (!date) {
        dispatch(
          redux.actionContainer.showAlertAsync({
            type: 'warning',
            title: t('WARNING'),
            message: t(
              'PLEASE_SELECT_CORRECTION_DATE_AND_SELECT_MATERIALS_IF_NEEDED_FOR_THIS_WARRANTY_THEN_SUBMIT',
            ),
            isBackdropPress: false,
            buttonText: t('OK'),
            isHideModalOnClose: false,
            onClose: () => {
              dispatch(redux.actionContainer.hideAlertAsync());
            },
          }),
        );
        return;
      }

      if (!correctionNeeded.trim()) {
        dispatch(
          redux.actionContainer.showAlertAsync({
            type: 'warning',
            title: t('WARNING'),
            message: t(
              'PLEASE_SELECT_CORRECTION_DATE_AND_SELECT_MATERIALS_IF_NEEDED_FOR_THIS_WARRANTY_THEN_SUBMIT',
            ),
            isBackdropPress: false,
            buttonText: t('OK'),
            isHideModalOnClose: false,
            onClose: () => {
              dispatch(redux.actionContainer.hideAlertAsync());
            },
          }),
        );
        return;
      }

      const payload = {
        id: params?.id,
        correctionDate: dayjs(date, 'MM/DD/YYYY').toISOString(),
        correctionNeed: correctionNeeded.trim(),
        materials: materialsWarranty || [],
        goBack: () => {
          NavigationService.goBack();
          dispatch(redux.actionContainer.clearWarrantyData());
        },
      };

      dispatch(redux?.actionContainer?.submitWarrantyAsync(payload));
    } catch (error) {
      logger('handleSubmitWarranty', error);
      dispatch(
        redux?.actionContainer?.showAlertAsync({
          type: 'error',
          title: t('ERROR'),
          message: t('FAILED_TO_SUBMIT_WARRANTY'),
          isBackdropPress: false,
          buttonText: t('OK'),
          isHideModalOnClose: false,
          onClose: () => {
            dispatch(redux.actionContainer.hideAlertAsync());
          },
        }),
      );
    }
  };

  const fetchMaterialsWarranty = useCallback(async () => {
    try {
      if (materialsWarranty?.length > 0) {
        return;
      }
      const redux = await import('auth/redux');
      dispatch(
        redux.actionContainer.getMaterialsWarrantyAsync(jobsWarranty?.id),
      );
    } catch (error) {
      logger('MaterialsWarranty', error);
    }
  }, [jobsWarranty?.id]);

  useEffect(() => {
    fetchMaterialsWarranty();
  }, [fetchMaterialsWarranty]);

  useEffect(() => {
    fetchJobWarrantyDetail();
  }, [fetchJobWarrantyDetail]);

  return (
    <BaseContainer style={styles.container}>
      <HeaderBase
        title={t('MY_JOB_DETAIL')}
        onPressBack={async () => {
          try {
            const redux = await import('auth/redux');
            NavigationService.goBack();
            dispatch(redux.actionContainer.clearWarrantyData());
          } catch (error) {
            logger('onPressBack', error);
          }
        }}
      />

      {!isLoading && (
        <ScrollView>
          <Detail
            community={
              jobsWarranty?.comunityName || jobsWarranty?.communityCode || '-'
            }
            address={jobsWarranty?.address}
            lotNumber={jobsWarranty?.lotNumber}
            estStartDate={
              jobsWarranty?.soDate
                ? dayjs(jobsWarranty.soDate).format('MMM DD, YYYY')
                : '-'
            }
            status={jobsWarranty?.statusName}
          />
          <Description description={jobsWarranty?.description} />
          <Response
            setDate={setDate}
            date={date}
            correctionNeeded={correctionNeeded}
            setCorrectionNeeded={setCorrectionNeeded}
          />
          <Comment chatId={jobsWarranty?.chatId} />
        </ScrollView>
      )}

      {jobsWarranty?.status === WARRANTY_STATUS.PENDING && !isLoading && (
        <Button
          disabled={isLoadingSubmitWarranty}
          isLoading={isLoadingSubmitWarranty}
          style={[styles.addButton]}
          onPress={handleSubmitWarranty}
        >
          <Text style={styles.addButtonText}>{t('SUBMIT')}</Text>
        </Button>
      )}
    </BaseContainer>
  );
};

export default WarrantyJobDetail;
