import React, { useCallback } from 'react';
import { FlatList, View } from 'react-native';
import {
  BaseContainer,
  HeaderBase,
  Text,
  Button,
  BottomSelector,
  SCREEN_WIDTH,
} from 'tradewize-component';
import { SvgXml } from 'react-native-svg';
import { colors } from '../../theme';
import { useAppTranslation } from '../../hooks/useAppTranslation';
import useMaterialLeft from '../../hooks/useMaterialLeft';
import type {
  MaterialLeftFlatRow,
  MaterialLeftHeaderRow,
  MaterialLeftItemRow,
} from '../../hooks/useMaterialLeft';
import { IconComment } from '../../assets/svg';
import { styles } from './styles';
import type { MaterialLeftItem } from '../../types/jobDetail.type';
import CommentChecklist from '../../components/CommentChecklist';

// ============================================================================
// Sub Components
// ============================================================================

interface MaterialItemCardProps {
  item: MaterialLeftItem;
  isViewMode: boolean;
  onQuantityPress: (unitkey: string, maxQuantity: number) => void;
  onCommentPress?: (item: MaterialLeftItem) => void;
  getInitialValue: (item: MaterialLeftItem) => string | undefined;
  t: (key: string) => string;
}

const MaterialItemCard: React.FC<MaterialItemCardProps> = React.memo(
  ({
    item,
    isViewMode,
    onQuantityPress,
    onCommentPress,
    getInitialValue,
    t,
  }) => {
    const quantityLabel = getInitialValue(item);

    const handlePress = useCallback(() => {
      if (!isViewMode) {
        onQuantityPress(item.unitkey, item.quantity);
      }
    }, [isViewMode, item.unitkey, item.quantity, onQuantityPress]);

    const handleComment = useCallback(() => {
      onCommentPress?.(item);
    }, [onCommentPress, item]);

    return (
      <View style={styles.materialItemContainer}>
        <View style={styles.materialItem}>
          <View style={styles.materialInfo}>
            <Text style={styles.materialName}>{item.materialName}</Text>
            <Text style={styles.materialDetails}>
              {t('COLOR')}: {item.colorName || '-'}
            </Text>
            <Text style={styles.materialDetails}>
              {t('SIZE')}: {item.size || '-'} - U/M: {item.unitTypeName || '-'}
            </Text>
            <Text style={styles.materialDetails}>
              {t('TRUE_MEASUREMENTS')}: {item.measurements || '-'}
            </Text>
          </View>

          {/* Comment Icon - top right */}
          <Button style={styles.commentButton} onPress={handleComment}>
            <SvgXml
              xml={IconComment(colors.mainColorPrimary)}
              width={SCREEN_WIDTH * 0.06}
              height={SCREEN_WIDTH * 0.06}
            />
          </Button>
        </View>

        {/* Quantity Left Selector */}
        <Button
          style={styles.toggleContainer}
          onPress={handlePress}
          disabled={isViewMode}
          activeOpacity={0.7}
        >
          <View style={styles.toggleWrapper}>
            <Text style={styles.selectorLabel}>{t('MATERIAL_LEFT')}</Text>
            <View style={styles.selectedValueContainer}>
              <Text
                style={
                  quantityLabel
                    ? styles.selectedValueText
                    : styles.placeholderText
                }
              >
                {quantityLabel ?? t('PLEASE_SELECT_MATERIAL_LEFT')}
              </Text>
            </View>
          </View>
          {isViewMode && <View style={styles.overlay} />}
        </Button>
      </View>
    );
  },
);

// ============================================================================
// Section Header
// ============================================================================

interface SectionHeaderProps {
  title: string;
  count: number;
}

const SectionHeader: React.FC<SectionHeaderProps> = React.memo(
  ({ title, count }) => (
    <View style={styles.typeHeader}>
      <View style={styles.typeHeaderContent}>
        <Text style={styles.typeTitle}>
          <Text style={styles.typeTitleBold}>{title}</Text>
          {'  '}
          <Text style={styles.typeTitleCount}>({count})</Text>
        </Text>
      </View>
    </View>
  ),
);

// ============================================================================
// Main Screen
// ============================================================================

const keyExtractor = (row: MaterialLeftFlatRow) => row.key;

const VerifyMaterialLeftScreen: React.FC = () => {
  const { t } = useAppTranslation();

  const {
    flatListData,
    isLoading,
    isViewMode,
    isSubmitting,
    isMaterialLeft,
    submitMaterial,
    handleGoBack,
    handleCommentPress,
    getInitialValue,
    isSelectorVisible,
    quantityOptions,
    setIsSelectorVisible,
    openQuantitySelector,
    handleSelectQuantity,
  } = useMaterialLeft();

  const handleQuantityPress = useCallback(
    (unitkey: string, maxQuantity: number) => {
      openQuantitySelector(unitkey, maxQuantity);
    },
    [openQuantitySelector],
  );

  const renderItem = useCallback(
    ({ item: row }: { item: MaterialLeftFlatRow }) => {
      if (row.type === 'header') {
        const header = row as MaterialLeftHeaderRow;
        return <SectionHeader title={header.title} count={header.count} />;
      }

      const itemRow = row as MaterialLeftItemRow;
      return (
        <MaterialItemCard
          item={itemRow.data}
          isViewMode={isViewMode}
          onQuantityPress={handleQuantityPress}
          onCommentPress={handleCommentPress}
          getInitialValue={getInitialValue}
          t={t}
        />
      );
    },
    [isViewMode, handleQuantityPress, handleCommentPress, getInitialValue, t],
  );

  const isHideSubmit = isViewMode || !isMaterialLeft;

  const ListHeaderComponent = useCallback(
    () => (
      <Text style={styles.description}>
        {t('PLEASE_VERIFY_MATERIAL_LEFT_DESCRIPTION_2')}
      </Text>
    ),
    [t],
  );

  const handleCloseSelector = useCallback(() => {
    setIsSelectorVisible(false);
  }, [setIsSelectorVisible]);

  return (
    <BaseContainer>
      <HeaderBase
        title={t('VERIFY_MATERIAL_LEFT')}
        onPressBack={handleGoBack}
        backgroundColor={colors.white}
        colorIconLeft={colors.grayScale100}
        titleStyle={styles.headerTitle}
      />

      {!isLoading && (
        <>
          <FlatList
            data={flatListData}
            renderItem={renderItem}
            keyExtractor={keyExtractor}
            ListHeaderComponent={ListHeaderComponent}
            style={styles.container}
            contentContainerStyle={styles.contentContainer}
            showsVerticalScrollIndicator={false}
          />

          {/* Submit Button */}
          <View
            style={[
              styles.submitButtonContainer,
              isHideSubmit && styles.hideButton,
            ]}
          >
            <Button
              style={[
                styles.submitButton,
                isSubmitting && styles.submitButtonDisabled,
              ]}
              onPress={submitMaterial}
              disabled={isSubmitting}
            >
              <Text
                style={[
                  styles.submitButtonText,
                  isSubmitting && styles.submitButtonTextDisabled,
                ]}
              >
                {t('SUBMIT')}
              </Text>
            </Button>
          </View>
        </>
      )}

      {/* Quantity Selector Bottom Sheet */}
      <BottomSelector
        title={t('MATERIAL_LEFT')}
        options={quantityOptions}
        isVisible={isSelectorVisible}
        onClose={handleCloseSelector}
        onSelect={handleSelectQuantity}
        containerStyle={styles.selectorContainer}
        enableSearch={true}
      />

      {/* Comment Checklist Modal */}
      <CommentChecklist />
    </BaseContainer>
  );
};

export default VerifyMaterialLeftScreen;

