import { logger } from '../../utils';

const getBaseFilePo = '/api/work-orders/get-base-file-po';
const getFileFromPresignUrl = '/api/files/presigned-url';

export const getPdfFile = async (id: string = '') => {
  const redux = await import('auth/redux');
  const client = await import('auth/api');

  try {
    redux.store.dispatch(redux.actionContainer.showLoadingOverlay());
    const response = await client.getRequest(getBaseFilePo, {
      params: {
        purchaseOrderId: id,
      },
      headers: {
        Accept: 'text/plain',
      },
    });

    if (response.status !== 200) {
      redux.store.dispatch(
        redux.actionContainer.showAlertAsync({
          message: response?.data?.message || 'Error',
          type: 'error',
        }),
      );
      return '';
    }

    const encodedKey = encodeURIComponent(response?.data?.key);
    const getFileFrom = await client.getRequest(
      `${getFileFromPresignUrl}/${encodedKey}`,
    );

    if (getFileFrom && getFileFrom.status !== 200) {
      redux.store.dispatch(
        redux.actionContainer.showAlertAsync({
          message: getFileFrom?.data?.message || 'Error',
          type: 'error',
        }),
      );
      return '';
    }

    return getFileFrom?.data;
  } catch (error) {
    logger('error getPdfFile', error);
  } finally {
    redux.store.dispatch(redux.actionContainer.hideLoadingOverlay());
  }
};
