import React from 'react';
import {
  View,
  StyleSheet,
  FlatList,
  ActivityIndicator,
} from 'react-native';
import {
  BaseContainer,
  HeaderBase,
  Text,
} from 'tradewize-component';
import { colors } from '../../theme';
import { useAppTranslation } from '../../hooks/useAppTranslation';
import { useOtherCrewMembers } from '../../hooks/useOtherCrewMembers';
import ParticipantItem from './components/ParticipantItem';
import { CrewParticipant } from '../../types/jobDetail.type';

const OtherCrewMembersScreen: React.FC = () => {
  const { t } = useAppTranslation();
  const {
    participants,
    isLoading,
    error,
    totalCount,
    getStatusInfo,
    getProgress,
    handleGoBack,
    handleParticipantPress,
  } = useOtherCrewMembers();

  const renderItem = ({ item }: { item: CrewParticipant }) => {
    const statusInfo = getStatusInfo(t, item.status);
    const progress = getProgress(item);

    return (
      <ParticipantItem
        participant={item}
        statusColor={statusInfo.color}
        statusText={statusInfo.text}
        progress={progress}
        onPress={handleParticipantPress}
      />
    );
  };

  const renderEmpty = () => (
    <View style={styles.emptyContainer}>
      <Text style={styles.emptyText}>{t('NO_PARTICIPANTS_FOUND')}</Text>
    </View>
  );

  return (
    <BaseContainer>
      <HeaderBase
        title={t('OTHER_CREW_MEMBERS')}
        onPressBack={handleGoBack}
        backgroundColor={colors.white}
        colorIconLeft={colors.grayScale100}
        titleStyle={styles.headerTitle}
      />
      {!isLoading && (
        <>
          <View style={styles.countContainer}>
            <View style={styles.countLabel}>
              <Text style={styles.countTitle}>{t('MEMBERS')}</Text>
              <View style={styles.countBadge}>
                <Text style={styles.countBadgeText}>{totalCount}</Text>
              </View>
            </View>
          </View>
          <FlatList
            data={participants}
            keyExtractor={item => item.id}
            renderItem={renderItem} 
            contentContainerStyle={styles.listContent}
            showsVerticalScrollIndicator={false}
            ListEmptyComponent={renderEmpty}
          />
        </>
      )}
    </BaseContainer>
  );
};

const styles = StyleSheet.create({
  headerTitle: {
    fontSize: 18,
    fontWeight: '600',
    color: colors.grayScale100,
  },
  countContainer: {
    backgroundColor: colors.white,
    marginHorizontal: 16,
    marginTop: 16,
    marginBottom: 8,
    padding: 16,
    borderRadius: 12,
    shadowColor: '#000',
    shadowOffset: { width: 0, height: 2 },
    shadowOpacity: 0.05,
    shadowRadius: 4,
    elevation: 2,
  },
  countLabel: {
    flexDirection: 'row',
    justifyContent: 'space-between',
    alignItems: 'center',
  },
  countTitle: {
    fontSize: 18,
    fontWeight: '600',
    color: colors.grayScale100,
  },
  countBadge: {
    backgroundColor: '#1E40AF',
    width: 28,
    height: 28,
    borderRadius: 14,
    justifyContent: 'center',
    alignItems: 'center',
  },
  countBadgeText: {
    color: colors.white,
    fontSize: 14,
    fontWeight: '600',
  },
  listContent: {
    padding: 16,
    paddingTop: 8,
  },
  loadingContainer: {
    flex: 1,
    justifyContent: 'center',
    alignItems: 'center',
  },
  emptyContainer: {
    flex: 1,
    justifyContent: 'center',
    alignItems: 'center',
    paddingTop: 100,
  },
  emptyText: {
    fontSize: 16,
    color: colors.grayScale70,
  },
  errorContainer: {
    flex: 1,
    justifyContent: 'center',
    alignItems: 'center',
    paddingTop: 100,
    paddingHorizontal: 32,
  },
  errorText: {
    fontSize: 16,
    color: colors.alertColorError,
    textAlign: 'center',
  },
});

export default OtherCrewMembersScreen;
