import { useEffect, useState, useMemo, useCallback } from 'react';
import { useRoute } from '@react-navigation/native';
import { NavigationService } from '../services/NavigationService';
import { dispatch } from '../helper';
import { logger } from '../utils';
import { actionContainer } from '../../../Auth/src/redux';
import type { MaterialLeftItem } from '../types/jobDetail.type';
import type { BottomSelectorOption } from 'tradewize-component';
import { generateQuantityOptions } from '../helper/jobStart.helper';
import { useAppSelector } from '../../../Auth/src/redux/store/types';
import { SCREEN_KEY_MATERIAL_LEFT } from '../../../Auth/src/redux/features/jobDetail/contants';

// ============================================================================
// Types
// ============================================================================

interface RouteParams {
  scheduleActivityId: string;
  onGoBack?: () => void;
}

interface GroupedMaterials {
  [key: string]: MaterialLeftItem[];
}

export type MaterialLeftHeaderRow = {
  type: 'header';
  key: string;
  title: string;
  count: number;
};

export type MaterialLeftItemRow = {
  type: 'item';
  key: string;
  data: MaterialLeftItem;
};

export type MaterialLeftFlatRow = MaterialLeftHeaderRow | MaterialLeftItemRow;

// ============================================================================
// Hook
// ============================================================================

const useMaterialLeft = () => {
  const route = useRoute<any>();
  const { scheduleActivityId, onGoBack } = (route.params || {}) as RouteParams;

  // Redux State
  const materialLeftState = useAppSelector(
    (state: any) => state.jobDetail?.materialLeftData,
  );
  const dataMaterial = useMemo(
    () => (materialLeftState?.data as MaterialLeftItem[]) || [],
    [materialLeftState?.data],
  );
  const isLoading = materialLeftState?.isLoading ?? true;
  const isViewMode = materialLeftState?.isSubmitted ?? false;

  // Local state for quantity edits (not persisted to Redux until submit)
  const [localQuantities, setLocalQuantities] = useState<
    Record<string, number | null>
  >({});
  const [isSubmitting, setIsSubmitting] = useState(false);

  // Bottom Selector state
  const [isSelectorVisible, setIsSelectorVisible] = useState(false);
  const [quantityOptions, setQuantityOptions] = useState<
    BottomSelectorOption[]
  >([]);
  const [selectedUnitKey, setSelectedUnitKey] = useState<string | null>(null);

  // ============================================================================
  // Fetch Data via Redux
  // ============================================================================

  useEffect(() => {
    if (scheduleActivityId) {
      dispatch(
        actionContainer.getMaterialLeftDataAsync({ scheduleActivityId }),
      );
    }

    return () => {
      dispatch(actionContainer.clearMaterialLeftData());
    };
  }, [scheduleActivityId]);

  // ============================================================================
  // Merged data: Redux data + local quantity edits
  // ============================================================================

  const mergedData = useMemo(() => {
    if (!Array.isArray(dataMaterial)) return [];
    return dataMaterial.map(item => {
      const localQty = localQuantities[item.unitkey || ''];
      return localQty !== undefined
        ? { ...item, quantityLeft: localQty }
        : item;
    });
  }, [dataMaterial, localQuantities]);

  // ============================================================================
  // Flat list data — flatten grouped materials for FlatList
  // ============================================================================

  const flatListData: MaterialLeftFlatRow[] = useMemo(() => {
    const rows: MaterialLeftFlatRow[] = [];
    if (!Array.isArray(mergedData)) return rows;

    // Group by materialGroupId
    const groups: GroupedMaterials = {};
    mergedData.forEach(item => {
      const typeId = item?.materialGroupId || 'unknown';
      if (!groups[typeId]) {
        groups[typeId] = [];
      }
      groups[typeId].push(item);
    });

    // Flatten: header + items for each group
    Object.entries(groups).forEach(([typeId, items]) => {
      rows.push({
        type: 'header',
        key: `header-${typeId}`,
        title: items[0]?.materialGroupName || 'Unknown Type',
        count: items.length,
      });
      items.forEach(item => {
        rows.push({
          type: 'item',
          key: item.unitkey,
          data: item,
        });
      });
    });

    return rows;
  }, [mergedData]);

  // Check if any material has quantityLeft > 0
  const isMaterialLeft = useMemo(() => {
    if (!Array.isArray(mergedData)) return false;
    return mergedData.some(item => (item?.quantityLeft ?? 0) > 0);
  }, [mergedData]);

  const openQuantitySelector = useCallback(
    (unitkey: string, maxQuantity: number) => {
      if (isViewMode) return;
      setSelectedUnitKey(unitkey);
      setQuantityOptions(generateQuantityOptions(maxQuantity));
      setIsSelectorVisible(true);
    },
    [isViewMode],
  );

  const handleSelectQuantity = useCallback(
    (option: BottomSelectorOption) => {
      if (!selectedUnitKey) return;
      const numericValue =
        option.value === '' ? null : parseFloat(option.value as string);

      setLocalQuantities(prev => ({
        ...prev,
        [selectedUnitKey]: numericValue,
      }));
      setIsSelectorVisible(false);
      setSelectedUnitKey(null);
    },
    [selectedUnitKey],
  );

  // Get initial value label for BottomSelector
  const getInitialValue = useCallback(
    (item: MaterialLeftItem): string | undefined => {
      // Check local edit first
      const localQty = localQuantities[item.unitkey || ''];
      if (localQty !== undefined) return localQty?.toString();

      const value =
        item.quantityLeft?.toString() || item.receivedQuantity2?.toString();
      return value || undefined;
    },
    [localQuantities],
  );

  // ============================================================================
  // Comment Handler — opens CommentChecklist modal via Redux
  // ============================================================================

  const handleCommentPress = useCallback(
    (item: MaterialLeftItem) => {
      dispatch(
        actionContainer.showCommentChecklistModal({
          visible: true,
          item: {
            ...item,
            id: item.materialId,
            name: item.materialName,
            scheduleActivityId,
            colorId: item.colorId,
          } as any,
          folderName: 'material-left',
          screenKey: SCREEN_KEY_MATERIAL_LEFT,
        }),
      );
    },
    [scheduleActivityId],
  );

  // ============================================================================
  // Submit Material Left via Redux
  // ============================================================================

  const submitMaterial = useCallback(async () => {
    if (isSubmitting || isViewMode) return;

    setIsSubmitting(true);

    const checklistItems = mergedData
      .filter(item => (item?.quantityLeft ?? 0) > 0)
      .map(item => ({
        colorId: item.colorId,
        materialId: item.materialId,
        materialTypeId: item.materialTypeId,
        quantity: item.quantity || 0,
        receivedQuantity: item.receivedQuantity || 0,
        quantitySave: item.quantitySave || 0,
        quantityLeft: item.quantityLeft || 0,
        leaderComment: '',
      }));

    dispatch(
      actionContainer.submitMaterialLeftAsync({
        scheduleActivityId,
        saveMaterialLeftData: checklistItems,
        onSuccess: () => {
          setIsSubmitting(false);
          onGoBack?.();
          NavigationService.goBack();
        },
        onError: () => {
          setIsSubmitting(false);
        },
      }),
    );
  }, [isSubmitting, isViewMode, mergedData, scheduleActivityId, onGoBack]);

  // ============================================================================
  // Save Comment via Redux
  // ============================================================================

  const handleSaveComment = useCallback(
    async (
      updatedItem: MaterialLeftItem,
      _isAutoCheckSuccess?: boolean,
      _checklistItemsCopy?: MaterialLeftItem[],
      _isCheckAfterByCheckType?: boolean,
      uploadResult?: any,
    ) => {
      const fileDatas = (uploadResult || [])
        .filter((file: any) => !file?.isOld)
        .map((file: any) => ({
          fileId: file?.fileId,
          key: file?.objectKey,
          url: file?.uploadFileUrl,
          fileName: file.fileName,
          fileLength: file.fileSize,
          fileExtension: file.fileType?.split('/')?.[1],
        }));

      dispatch(
        actionContainer.saveMaterialLeftCommentAsync({
          scheduleActivityId,
          materialId: updatedItem.materialId,
          colorId: updatedItem.colorId,
          items: [
            {
              comment: updatedItem.comment || '',
              fileKeys: fileDatas.map((file: any) => file.key),
            },
          ],
          onSuccess: () => {
            logger('Material left comment saved successfully');
          },
          onError: (error: any) => {
            logger('Error saving material left comment:', error);
          },
        }),
      );
    },
    [scheduleActivityId],
  );

  // ============================================================================
  // Navigation
  // ============================================================================

  const handleGoBack = useCallback(() => {
    NavigationService.goBack();
  }, []);

  return {
    // Data
    dataMaterial: mergedData,
    flatListData,
    isLoading,
    isViewMode,
    isSubmitting,
    isMaterialLeft,

    // Actions
    submitMaterial,
    handleSaveComment,
    handleCommentPress,
    handleGoBack,
    getInitialValue,

    // Bottom Selector
    isSelectorVisible,
    quantityOptions,
    setIsSelectorVisible,
    openQuantitySelector,
    handleSelectQuantity,
  };
};

export default useMaterialLeft;

