import React, { useEffect, useRef } from "react";

interface StoreWrapperProps {
  store: any;
  onReady: (store: any) => void;
  children: (store: any) => React.ReactNode;
}

/**
 * Notifies parent once when store becomes available,
 * then renders children with the store instance.
 */
export const StoreWrapper = ({
  store,
  onReady,
  children,
}: StoreWrapperProps) => {
  const hasNotifiedRef = useRef(false);

  useEffect(() => {
    if (store && !hasNotifiedRef.current) {
      hasNotifiedRef.current = true;
      onReady(store);
    }
  }, [store, onReady]);

  return <>{children(store)}</>;
};

interface EntryProps {
  AuthProvider: React.ComponentType<any>;
  onReady: (store: any) => void;
  children: (store: any) => React.ReactNode;
}

/**
 * Wraps children with AuthProvider + StoreWrapper.
 * AuthProvider is injected as a prop so each module can load it differently
 * (Host uses loadRemote, Content uses React.lazy).
 */
export const Entry = ({ AuthProvider, onReady, children }: EntryProps) => {
  return (
    <React.Suspense fallback={null}>
      <AuthProvider>
        {(store: any) => (
          <StoreWrapper store={store} onReady={onReady} children={children} />
        )}
      </AuthProvider>
    </React.Suspense>
  );
};
