import { AxiosResponse } from 'axios';
import { useEffect, useState } from 'react';
import { useDispatch } from 'react-redux';
import { getDeliveryStatus } from '../api/endpoint';

interface Location {
  latitude: number;
  longitude: number;
}

interface DriverLocationData {
  purchaseOrderId: string;
  driverId: string;
  driverFullName: string;
  deliveryStart: string;
  location: Location;
  status: number;
  statusName: string;
}

interface ApiResponseData {
  data: DriverLocationData;
  statusCode: number;
  succeeded: boolean;
  code: string;
  message: string;
  detailedError: string | null;
}

interface useTrackingDriverProps {
  purchaseOrderId: string;
}

export const useTrackingDriver = ({
  purchaseOrderId,
}: useTrackingDriverProps) => {
  const dispatch = useDispatch();
  const [locationDriverServer, setLocationDriverServer] =
    useState<DriverLocationData | null>(null);
  const [isLoading, setIsLoading] = useState(false);

  useEffect(() => {
    const fetchLocationJob = async (isInitialLoad: boolean = false) => {
      try {
        const redux = await import('auth/redux');
        const client = await import('auth/api');
        if (isInitialLoad) {
          dispatch(redux.actionContainer.showLoadingOverlay());
        }
        setIsLoading(true);
        const response: AxiosResponse<ApiResponseData> = await client.AppApi.get(
          `${getDeliveryStatus}/${purchaseOrderId}`,
        );

        if (response?.status === 200 && response.data) {
          setLocationDriverServer(response?.data?.data);
        }
      } catch (error) {
        console.log('error fetchLocationJob', error);
      } finally {
        setIsLoading(false);
        const redux = await import('auth/redux');
        if (isInitialLoad) {
          dispatch(redux.actionContainer.hideLoadingOverlay());
        }
      }
    };

    // Initial fetch with loading
    fetchLocationJob(true);

    // Set up interval to fetch every minute without loading
    const intervalId = setInterval(() => fetchLocationJob(false), 60000);

    // Cleanup interval on unmount
    return () => {
      clearInterval(intervalId);
    };
  }, [purchaseOrderId, dispatch]);

  return { isLoading, locationDriverServer, setLocationDriverServer };
};
