import React from 'react';
import { StyleSheet, View } from 'react-native';
import { Text } from 'tradewize-component';
import colors from '../../../theme/colors';
import { formatCurrency } from '../../../utils/curencyUtil';
import { formatDate } from '../../../utils/index';
import { useAppTranslation } from '../../../hooks/useAppTranslation';

interface ReferralBonusCardProps {
  id: string;
  amount: number;
  estimatedPaymentDate: string | null;
  totalAmount: number;
  paymentStatus: number;
}

const ReferralBonusCard: React.FC<ReferralBonusCardProps> = ({
  amount,
  paymentStatus,
  estimatedPaymentDate,
  totalAmount,
}) => {
  const { t } = useAppTranslation();

  const getStatusText = () => {
    switch (paymentStatus) {
      case 0:
        return 'Open';
      case 1:
        return 'InComing';
      case 2:
        return 'Paid';
      default:
        return 'Open';
    }
  };

  const getCardBorderColor = () => {
    switch (paymentStatus) {
      case 0:
        return colors.grayScale20;
      case 1:
        return colors.lightBlue;
      case 2:
        return colors.greenBackground;
      default:
        return colors.grayScale20;
    }
  };

  const getStatusBackgroundColor = () => '#E3F2FD';

  const getStatusTextColor = () => {
    switch (paymentStatus) {
      case 0:
        return colors.grayScale70;
      case 1:
        return colors.black;
      case 2:
        return colors.mainColorPrimary;
      default:
        return colors.grayScale20;
    }
  };

  const formatPaymentLabel = () => {
    if (paymentStatus === 2) {
      return t('PAID_DATE') + ':';
    }
    return t('EST_PAY_DATE') + ':';
  };

  const formatDateValue = (dateString: string | null) => {
    if (!dateString) return t('FUTURE');
    const date = new Date(dateString);
    if (isNaN(date.getTime())) return t('FUTURE');
    return formatDate(date) || t('FUTURE');
  };

  const formatAmount = () => {
    const formatted = formatCurrency(totalAmount);
    if (formatted) {
      return `+${formatted}`;
    }
    const numericValue = Number(totalAmount);
    if (!Number.isFinite(numericValue)) return '';
    return `+$${numericValue.toFixed(2)}`;
  };

  return (
    <View
      style={[
        styles.card,
        { borderColor: getCardBorderColor() },
      ]}
    >
      <View style={styles.cardHeader}>
        <View style={styles.leftSection}>
          <Text style={styles.referralText}>
            {t('REFERRAL')} {t('BONUS')}
          </Text>
        </View>
        <View style={styles.rightSection}>
          <Text style={styles.amount}>{formatAmount()}</Text>
          <View
            style={[
              styles.statusTag,
              { backgroundColor: getStatusBackgroundColor() },
            ]}
          >
            <Text style={[styles.statusText, { color: getStatusTextColor() }]}>
              {getStatusText()}
            </Text>
          </View>
        </View>
      </View>

      <View style={styles.expandedContent}>
        <View style={styles.detailRow}>
          <Text style={styles.label}>{formatPaymentLabel()}</Text>
          <Text style={styles.value}>
            {formatDateValue(estimatedPaymentDate)}
          </Text>
        </View>
      </View>
    </View>
  );
};

const styles = StyleSheet.create({
  card: {
    backgroundColor: colors.white,
    borderRadius: 12,
    padding: 16,
    marginBottom: 12,
    borderWidth: 1,
    borderColor: colors.lightGray2,
    shadowColor: colors.black,
    shadowOffset: {
      width: 0,
      height: 2,
    },
    shadowOpacity: 0.1,
    shadowRadius: 4,
    elevation: 3,
  },
  cardHeader: {
    flexDirection: 'row',
    justifyContent: 'space-between',
    alignItems: 'flex-start',
  },
  leftSection: {
    flex: 1,
  },
  rightSection: {
    alignItems: 'flex-end',
  },
  referralText: {
    fontSize: 16,
    color: colors.black,
    fontWeight: '700',
    marginBottom: 8,
  },
  amount: {
    fontSize: 16,
    color: '#4CAF50',
    fontWeight: '700',
    marginBottom: 4,
  },
  statusTag: {
    borderRadius: 12,
    paddingHorizontal: 10,
    paddingVertical: 4,
    alignSelf: 'flex-end',
    marginTop: 4,
    backgroundColor: '#E3F2FD',
  },
  statusText: {
    fontSize: 12,
  },
  expandedContent: {
    marginTop: 16,
    paddingTop: 16,
    borderTopWidth: 1,
    borderTopColor: colors.basicWhiteGray,
  },
  detailRow: {
    flexDirection: 'row',
    justifyContent: 'space-between',
    marginBottom: 12,
  },
  label: {
    fontSize: 14,
    color: colors.twColors.text.secondary,
  },
  value: {
    fontSize: 14,
    color: colors.twColors.text.black,
    fontFamily: 'Medium',
  },
});

export default ReferralBonusCard;
