import React from 'react';
import { View } from 'react-native';
import { SCREEN_WIDTH, Text } from 'tradewize-component';
import { styles } from '../styles';
import { AddressData } from '../../../../../types/myJobs.types';
import { SvgXml } from 'react-native-svg';
import { colors } from '../../../../../theme';
import { IconLocation } from '../../../../../assets/svg';
import { useAppTranslation } from '../../../../../hooks/useAppTranslation';

interface AddressProps {
  addressData: AddressData;
}

export default function Address({ addressData }: AddressProps) {
  const { t } = useAppTranslation();

  // Build address string
  const addressParts = [
    addressData.houseNumber,
    addressData.street,
    addressData.city,
    addressData.state,
  ].filter(Boolean);

  const fullAddress = addressParts.join(', ');

  return (
    <View style={styles.addressRow}>
      <View style={styles.addressContent}>
        <SvgXml
          xml={IconLocation(colors.black)}
          width={SCREEN_WIDTH * 0.05}
          height={SCREEN_WIDTH * 0.05}
        />
        <Text numberOfLines={2} style={styles.txtAddress}>
          {fullAddress} - {t('LOT')}: {addressData.lotNumber}
        </Text>
      </View>
    </View>
  );
}
