import React, { useRef, useState } from 'react';
import { View, Modal, StyleSheet, TouchableOpacity, ScrollView } from 'react-native';
import { Text, Button } from 'tradewize-component';
import Signature, { SignatureViewRef } from 'react-native-signature-canvas';
import { colors } from '../../../theme';
import { useAppTranslation } from '../../../hooks/useAppTranslation';

interface SignatureModalProps {
  visible: boolean;
  onClose: () => void;
  onConfirm: (signatureUrl: string) => void;
}

export default function SignatureModal({
  visible,
  onClose,
  onConfirm,
}: SignatureModalProps) {
  const { t } = useAppTranslation();
  const signatureRef = useRef<SignatureViewRef>(null);

  const handleOK = (signature: string) => {
    onConfirm(signature);
    onClose();
  };

  const handleClear = () => {
    signatureRef.current?.clearSignature();
  };

  const handleConfirm = () => {
    signatureRef.current?.readSignature();
  };

  return (
    <Modal
      visible={visible}
      animationType="slide"
      transparent={true}
      onRequestClose={onClose}
    >
      <View style={styles.modalContainer}>
        <View style={styles.modalContent}>
          <Text style={styles.modalTitle}>{t('E_SIGNATURE_REQUIRED')}</Text>
          <Text style={styles.modalSubtitle}>
            {t('PLEASE_SIGN_TO_COMPLETE_THIS_JOB')}
          </Text>

          <View style={styles.signatureCanvasContainer}>
            <Signature
              ref={signatureRef}
              style={styles.signatureCanvas}
              onOK={handleOK}
              descriptionText={t('SIGN_HERE')}
              clearText={t('CLEAR')}
              confirmText={t('CONFIRM')}
              webStyle={`
                .m-signature-pad--footer { display: none; margin: 0px; }
                .m-signature-pad--body { border: none; }
              `}
            />
          </View>

          <View style={styles.buttonGroup}>
            <Button
              variant="outline"
              style={[styles.actionButton, styles.cancelButton]}
              onPress={onClose}
            >
              <Text style={styles.cancelText}>{t('CANCEL')}</Text>
            </Button>
            <Button
              variant="outline"
              style={[styles.actionButton, styles.clearButton]}
              onPress={handleClear}
            >
              <Text style={styles.clearText}>{t('CLEAR')}</Text>
            </Button>
            <Button
              variant="primary"
              style={styles.actionButton}
              onPress={handleConfirm}
            >
              <Text style={styles.confirmText}>{t('CONFIRM')}</Text>
            </Button>
          </View>
        </View>
      </View>
    </Modal>
  );
}

const styles = StyleSheet.create({
  modalContainer: {
    flex: 1,
    backgroundColor: 'rgba(0, 0, 0, 0.5)',
    justifyContent: 'center',
    alignItems: 'center',
  },
  modalContent: {
    width: '90%',
    backgroundColor: colors.white,
    borderRadius: 12,
    padding: 20,
    alignItems: 'center',
  },
  modalTitle: {
    fontSize: 18,
    fontWeight: 'bold',
    color: colors.black,
    marginBottom: 8,
  },
  modalSubtitle: {
    fontSize: 14,
    color: colors.grayScale60,
    marginBottom: 20,
    textAlign: 'center',
  },
  signatureCanvasContainer: {
    width: '100%',
    height: 250,
    borderWidth: 1,
    borderColor: colors.grayScale30,
    borderRadius: 8,
    overflow: 'hidden',
    backgroundColor: '#fff',
    marginBottom: 20,
  },
  signatureCanvas: {
    width: '100%',
    height: '100%',
  },
  buttonGroup: {
    flexDirection: 'row',
    justifyContent: 'space-between',
    width: '100%',
  },
  actionButton: {
    flex: 1,
    marginHorizontal: 5,
  },
  cancelButton: {
    borderColor: colors.grayScale40,
  },
  clearButton: {
    borderColor: colors.alertColorError,
  },
  cancelText: {
    color: colors.grayScale60,
    fontWeight: 'bold',
  },
  clearText: {
    color: colors.alertColorError,
    fontWeight: 'bold',
  },
  confirmText: {
    color: colors.white,
    fontWeight: 'bold',
  },
});
