import { useRoute } from '@react-navigation/native';
import React, { useEffect, useState } from 'react';
import { FlatList, View } from 'react-native';
import { styles } from './styles';
import { ShadowedView } from 'react-native-fast-shadow';
import { colors } from '../../theme';
import { getFileFromS3Key } from './helper';
import { BaseContainer, HeaderBase, Text } from 'tradewize-component';
import { FileThumbnail, FileViewer } from '../../components/FileViewer';
import { useDispatch } from 'react-redux';
import { useAppTranslation } from '../../hooks/useAppTranslation';
import { NavigationService } from '../../services/NavigationService';

const ToolsReededScreen = () => {
  const dispatch = useDispatch();
  const route: any = useRoute();
  const toolsNeededData = route?.params?.toolNeededData || [];
  const [finalData, setFinalData] = useState<any[]>([]);
  const [isModalVisible, setIsModalVisible] = useState(false);
  const [selectedMedia, setSelectedMedia] = useState<any>(null);
  const { t } = useAppTranslation();

  const renderItem = ({
    item,
  }: {
    item: {
      id: string;
      name: string;
      code: null;
      description: string;
      imageTool: null | string;
      uri: string;
    };
  }) => {
    return (
      <ShadowedView style={[styles.item, styles.shadowImg]}>
        {item?.uri ? (
          <FileThumbnail
            file={{ url: item.uri, type: 'image' }}
            readOnly={true}
            size="medium"
            onPress={() => {
              setIsModalVisible(true);
              setSelectedMedia({ url: item.uri, type: 'image' });
            }}
          />
        ) : (
          <View style={[styles.img, { backgroundColor: colors.gray }]} />
        )}

        <View style={styles.txtContent}>
          <Text style={styles.txtBtn}>{item?.name}</Text>
          <Text style={styles.des}>{item?.description}</Text>
        </View>
      </ShadowedView>
    );
  };

  useEffect(() => {
    const fetchData = async () => {
      const redux = await import('auth/redux');

      try {
        dispatch(redux.actionContainer.showLoadingOverlay());
        if (!toolsNeededData) {
          return;
        }

        const result = await Promise.all(
          toolsNeededData.map(async (item: any) => ({
            ...item,
            uri: item?.imageTool ? await getFileFromS3Key(item.imageTool) : '',
          })),
        );

        setFinalData(result);
      } catch (error) {
        console.error('Error fetching tools data:', error);
      } finally {
        dispatch(redux.actionContainer.hideLoadingOverlay());
      }
    };

    fetchData();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  return (
    <BaseContainer style={styles.container}>
      <HeaderBase
        onPressBack={() => NavigationService.goBack()}
        title={t('TOOLS_NEEDED')}
        containerStyle={styles.header}
      />

      <View style={styles.body}>
        <FlatList
          style={styles.flatList}
          data={finalData}
          renderItem={renderItem}
          keyExtractor={item => item?.id}
          removeClippedSubviews={false}
          contentContainerStyle={styles.contentContainer}
        />
      </View>

      {/* Media Preview Modal */}
      <FileViewer
        visible={isModalVisible}
        onClose={() => {
          setIsModalVisible(false);
          setSelectedMedia(null);
        }}
        file={selectedMedia}
      />
    </BaseContainer>
  );
};

export default ToolsReededScreen;
