import { WINDOW_HEIGHT, WINDOW_WIDTH } from '@gorhom/bottom-sheet';
import { useTrackingDriver } from '../../hooks/useTrackingDriver';
import { useRoute } from '@react-navigation/native';
import colors from '../../theme/colors';
import React, {
  useEffect,
  useRef,
  useMemo,
  useCallback,
  useState,
} from 'react';
import { Image, StyleSheet, View } from 'react-native';
import MapView, { Marker, PROVIDER_GOOGLE, Polyline } from 'react-native-maps';
import { useSafeAreaInsets } from 'react-native-safe-area-context';
import { IconArrowBack, IconLocation } from '../../assets/svg';
import { NavigationService } from '../../services/NavigationService';
// @ts-ignore
import polyline from '@mapbox/polyline';
import { destination, locationPointer } from '../../assets/images';
import { Button, SCREEN_WIDTH } from 'tradewize-component';
import { SvgXml } from 'react-native-svg';

const ASPECT_RATIO = WINDOW_WIDTH / WINDOW_HEIGHT;
const LATITUDE_DELTA = 0.015;
const LONGITUDE_DELTA = LATITUDE_DELTA * ASPECT_RATIO;

interface Coordinate {
  latitude: number;
  longitude: number;
}

const TrackingDriver = () => {
  const { job } = useRoute().params as { job: any };
  const locationJob = job?.location;
  const insets = useSafeAreaInsets();
  const mapRef = useRef<MapView>(null);
  const [routeCoordinates, setRouteCoordinates] = useState<Coordinate[]>([]);
  const [markerRotation, setMarkerRotation] = useState(0);
  const prevLocationRef = useRef<Coordinate | null>(null);

  const { locationDriverServer, isLoading } = useTrackingDriver({
    purchaseOrderId: job?.poDeliveryId,
  });

  const locationDriver = useMemo(() => {
    if (!isLoading && locationDriverServer?.location) {
      const newLocation = {
        latitude: locationDriverServer.location.latitude || 0,
        longitude: locationDriverServer.location.longitude || 0,
      };

      // Calculate rotation based on previous and current location
      if (prevLocationRef.current) {
        const dx = newLocation.longitude - prevLocationRef.current.longitude;
        const dy = newLocation.latitude - prevLocationRef.current.latitude;
        const rotation = (Math.atan2(dy, dx) * 180) / Math.PI;
        setMarkerRotation(rotation);
      }

      // Update previous location
      prevLocationRef.current = newLocation;
      return newLocation;
    }
    return null;
  }, [isLoading, locationDriverServer]);

  const calculateRotation = useCallback((coordinates: Coordinate[]) => {
    if (coordinates.length >= 2) {
      const toRad = (deg: number) => (deg * Math.PI) / 180;
      const toDeg = (rad: number) => (rad * 180) / Math.PI;

      const dLon = toRad(coordinates[1].longitude - coordinates[0].longitude);
      const y = Math.sin(dLon) * Math.cos(toRad(coordinates[1].latitude));
      const x =
        Math.cos(toRad(coordinates[0].latitude)) *
          Math.sin(toRad(coordinates[1].latitude)) -
        Math.sin(toRad(coordinates[0].latitude)) *
          Math.cos(toRad(coordinates[1].latitude)) *
          Math.cos(dLon);
      const brng = Math.atan2(y, x);
      const rotation = (toDeg(brng) + 360) % 360;
      setMarkerRotation(rotation);
    }
  }, []);

  const getDirections = useCallback(async () => {
    try {
      if (locationJob && locationDriver) {
        const url = `https://maps.googleapis.com/maps/api/directions/json?origin=${locationDriver.latitude},${locationDriver.longitude}&destination=${locationJob.latitude},${locationJob.longitude}&mode=driving&key=${process.env.GOOGLE_MAP_KEY}`;

        const response = await fetch(url);
        const json = await response.json();

        if (json.routes.length) {
          const points = json.routes[0].overview_polyline.points;
          const decodedPoints = polyline.decode(points);

          const coordinates = decodedPoints.map(([latitude, longitude]: [number, number]) => ({
            latitude,
            longitude,
          }));

          setRouteCoordinates(coordinates);
          calculateRotation(coordinates);
        }
      }
    } catch (error) {
      console.error('Error fetching directions:', error);
    }
  }, [locationJob, locationDriver, calculateRotation]);

  const fitToMarkers = useCallback(() => {
    if (locationJob && locationDriver && mapRef.current) {
      mapRef.current.fitToCoordinates(
        [
          { latitude: locationJob.latitude, longitude: locationJob.longitude },
          {
            latitude: locationDriver.latitude,
            longitude: locationDriver.longitude,
          },
        ],
        {
          edgePadding: {
            top: 100,
            right: 100,
            bottom: 100,
            left: 100,
          },
          animated: true,
        },
      );
    }
  }, [locationJob, locationDriver]);

  // Initial map setup
  useEffect(() => {
    const timer = setTimeout(() => {
      fitToMarkers();
    }, 1000); // Delay to ensure map is fully loaded

    return () => clearTimeout(timer);
  }, [fitToMarkers]);

  // Watch for location changes
  useEffect(() => {
    if (locationJob && locationDriver) {
      fitToMarkers();
    }
  }, [locationJob, locationDriver, fitToMarkers]);

  useEffect(() => {
    if (locationJob && locationDriver && !isLoading) {
      getDirections();
    }
  }, [locationJob, locationDriver, getDirections, isLoading]);

  const animateToLocation = () => {
    if (locationJob && locationDriver) {
      fitToMarkers();
    } else if (locationJob && mapRef.current) {
      mapRef.current.animateToRegion(
        {
          latitude: locationJob.latitude,
          longitude: locationJob.longitude,
          latitudeDelta: LATITUDE_DELTA,
          longitudeDelta: LONGITUDE_DELTA,
        },
        1000,
      );
    }
  };

  return (
    <View style={styles.container}>
      <View
        style={[styles.shadowGlobal, { ...styles.btnBack, top: insets.top + 10 }]}>
        <Button
          style={{ width: 44, height: 44, padding: 0 }}
          onPress={() => NavigationService.goBack()}
          variant="ghost"
        >
          <SvgXml xml={IconArrowBack()} width={SCREEN_WIDTH * 0.05} height={SCREEN_WIDTH * 0.05} />
        </Button>
      </View>
      <MapView
        ref={mapRef}
        provider={PROVIDER_GOOGLE}
        style={styles.map}
        initialRegion={{
          latitude: (locationJob?.latitude + locationDriver?.latitude) / 2 || 0,
          longitude:
            (locationJob?.longitude + locationDriver?.longitude) / 2 || 0,
          latitudeDelta: 0.1,
          longitudeDelta: 0.1,
        }}
        showsUserLocation
        showsCompass
        showsTraffic
        showsBuildings={true}
        mapType="standard">
        {locationJob && (
          <Marker
            coordinate={{
              latitude: locationJob.latitude,
              longitude: locationJob.longitude,
            }}>
            <Image
              source={destination}
              style={styles.destination}
              resizeMode="contain"
              tintColor={colors.red}
            />
          </Marker>
        )}
        {locationDriver && (
          <Marker
            coordinate={{
              latitude: locationDriver.latitude,
              longitude: locationDriver.longitude,
            }}
            rotation={markerRotation}
            anchor={{ x: 0.5, y: 0.5 }}>
            <Image
              source={locationPointer}
              style={styles.locationPointer}
              resizeMode="contain"
            />
          </Marker>
        )}
        {routeCoordinates && routeCoordinates.length > 0 && (
          <Polyline
            coordinates={routeCoordinates}
            strokeWidth={4}
            strokeColor={colors.mainColorPrimary}
            geodesic={true}
          />
        )}
      </MapView>
      <View style={[styles.shadowGlobal, {
            ...styles.locationButton,
            bottom: insets.bottom + 16,
          }]}>
        <Button
          style={{ width: 44, height: 44, padding: 0 }}
          onPress={animateToLocation}
          variant="ghost"
        >
          <SvgXml xml={IconLocation()} width={SCREEN_WIDTH * 0.05} height={SCREEN_WIDTH * 0.05} />
        </Button>
      </View>
    </View>
  );
};

const styles = StyleSheet.create({
  shadowGlobal: {
    shadowColor: '#000',
    shadowOffset: { width: 0, height: 2 },
    shadowOpacity: 0.25,
    shadowRadius: 3.84,
    elevation: 5,
  },
  container: {
    flex: 1,
    backgroundColor: colors.white,
  },
  btnBack: {
    position: 'absolute',
    left: 16,
    zIndex: 1000,
    backgroundColor: colors.white,
    borderRadius: 100,
  },
  locationButton: {
    position: 'absolute',
    right: 16,
    zIndex: 1000,
    backgroundColor: colors.white,
    borderRadius: 100,
  },
  map: {
    width: '100%',
    height: '100%',
  },
  locationPointer: {
    width: 32,
    height: 32,
    resizeMode: 'contain',
  },
  destination: {
    width: 48,
    height: 48,
    resizeMode: 'contain',
  },
});

export default TrackingDriver;
