import React from 'react';
import { View, ScrollView, Modal, Alert, Platform } from 'react-native';
import { Text, Button, Input } from 'tradewize-component';
import { SvgXml } from 'react-native-svg';
import ImagePicker from 'react-native-image-crop-picker';
import { PERMISSIONS } from 'react-native-permissions';
import Toast from 'react-native-toast-message';
import { IconClose } from '../../../assets/svg';
import { styles } from '../styles';
import { PhotoAttachment } from '../types';
import { sumArea } from '../helpers';
import ModalReportProgress from '../ModalReportProgress';

interface EditModalProps {
  visible: boolean;
  onClose: () => void;
  editModalSqft: string;
  editModalPhotos: PhotoAttachment[];
  editModalUploadResults: any[];
  editModalComment: string;
  editModalErrorSqft: string | null;
  isUploading: boolean;
  isSubmitting: boolean;
  canEdit: boolean;
  maxTodaySqft: number;
  progressPercentage: number;
  scrollViewRef: React.RefObject<ScrollView | null>;
  setEditModalSqft: (v: string) => void;
  setEditModalPhotos: (v: PhotoAttachment[]) => void;
  setEditModalUploadResults: (v: any[]) => void;
  setEditModalComment: (v: string) => void;
  setEditModalErrorSqft: (v: string | null) => void;
  setKeyboardOffset: (v: number) => void;
  setIsFocused: (v: boolean) => void;
  handleEditModalSqftChange: (text: string) => void;
  handleEditModalPhotoUpload: (
    asset: PhotoAttachment,
    direction: string,
    area: string,
  ) => Promise<void>;
  handleEditModalPhotoAreaChange: (index: number, area: string) => void;
  handleUpdate: (
    sqft?: string,
    photos?: PhotoAttachment[],
    uploadResults?: any[],
    comment?: string,
  ) => Promise<boolean>;
  checkPermission: (
    iosPer?: any,
    androidPer?: any,
    onBlocked?: () => void,
  ) => Promise<boolean>;
  t: (key: string) => string;
}

const EditModal = ({
  visible,
  onClose,
  editModalSqft,
  editModalPhotos,
  editModalUploadResults,
  editModalComment,
  editModalErrorSqft,
  isUploading,
  isSubmitting,
  canEdit,
  maxTodaySqft,
  progressPercentage,
  scrollViewRef,
  setEditModalSqft,
  setEditModalPhotos,
  setEditModalUploadResults,
  setEditModalComment,
  setEditModalErrorSqft,
  setKeyboardOffset,
  setIsFocused,
  handleEditModalSqftChange,
  handleEditModalPhotoUpload,
  handleEditModalPhotoAreaChange,
  handleUpdate,
  checkPermission,
  t,
}: EditModalProps) => {
  const resetAndClose = () => {
    setEditModalSqft('');
    setEditModalPhotos([]);
    setEditModalUploadResults([]);
    setEditModalComment('');
    setEditModalErrorSqft(null);
    onClose();
  };

  return (
    <Modal
      visible={visible}
      transparent={true}
      animationType="fade"
      onRequestClose={resetAndClose}
    >
      <View style={styles.editModalOverlay}>
        <View style={styles.editModalContainer}>
          {/* Modal Header */}
          <View style={styles.editModalHeader}>
            <Text style={styles.editModalTitle}>
              {t('EDIT_PROGRESS') || 'Edit Progress'}
            </Text>
            <Button
              variant="ghost"
              onPress={resetAndClose}
              style={styles.closeButtonModal}
            >
              <SvgXml xml={IconClose()} width={18} height={18} />
            </Button>
          </View>

          {/* Dashed Line */}
          <View style={styles.dashedLine} />

          {/* Modal Content */}
          <ScrollView
            ref={scrollViewRef}
            style={styles.editModalContent}
            showsVerticalScrollIndicator={false}
          >
            <ModalReportProgress
              helperView={
                <>
                  <View style={styles.errorSqftContainer}>
                    <Text style={styles.errorSqft}>{editModalErrorSqft}</Text>
                  </View>
                  <View
                    style={[
                      styles.sqftInputRow,
                      { width: '93%', alignSelf: 'center', marginTop: 12 },
                    ]}
                  >
                    <Text style={styles.sqftRowLabel}>
                      {t('TOTAL_INSTALLED_SQUARES')}:
                    </Text>
                    <Input
                      editable={false}
                      value={editModalSqft}
                      onChangeText={(text: string) => {
                        handleEditModalSqftChange(text);
                      }}
                      keyboardType="numeric"
                      inputStyle={styles.sqftInput}
                      inputContainerStyle={styles.sqftInput}
                      placeholder="0.00"
                      onFocus={() => {
                        setKeyboardOffset(Platform.OS === 'ios' ? 12 : 56);
                        setIsFocused(true);
                      }}
                      onBlur={() => {
                        setKeyboardOffset(0);
                        setIsFocused(false);
                      }}
                    />
                  </View>
                </>
              }
              photos={editModalPhotos}
              uploadResults={editModalUploadResults}
              isUploading={isUploading}
              onCameraPress={async (direction: string, area: string) => {
                if (editModalPhotos.length >= 5) {
                  Toast.show({
                    type: 'error',
                    text1: t('LIMIT_5_IMAGES'),
                  });
                  return;
                }

                const granted = await checkPermission(
                  PERMISSIONS.IOS.CAMERA,
                  PERMISSIONS.ANDROID.CAMERA,
                );

                if (!granted) {
                  return;
                }
                const result = await ImagePicker.openCamera({
                  mediaType: 'photo',
                  cropping: false,
                });

                if (result?.path) {
                  const asset: PhotoAttachment = {
                    uri: result.path,
                    type: result.mime || 'image/jpeg',
                    fileName:
                      result.path.split('/').pop() || `photo_${Date.now()}.jpg`,
                  };
                  await handleEditModalPhotoUpload(asset, direction, area);
                }
              }}
              onRemovePhoto={(index: number) => {
                const newPhotos = [...editModalPhotos];
                const newUploadResults = [...editModalUploadResults];
                newPhotos.splice(index, 1);
                newUploadResults.splice(index, 1);
                setEditModalPhotos(newPhotos);
                setEditModalUploadResults(newUploadResults);

                const hasEmptyArea = newPhotos.some(item => !item.area);
                const sumAreaValue = !hasEmptyArea
                  ? sumArea(newPhotos).toString()
                  : '';
                handleEditModalSqftChange(sumAreaValue);
              }}
              onAreaChange={handleEditModalPhotoAreaChange}
              comment={editModalComment}
              onCommentChange={setEditModalComment}
              canEdit={canEdit}
            />
          </ScrollView>

          {/* Modal Footer Buttons */}
          <View style={styles.editModalFooter}>
            <Button
              onPress={resetAndClose}
              variant="secondary"
              style={[styles.button, styles.closeButton]}
            >
              <Text style={styles.textBoldMediumBlack}>{t('CANCEL')}</Text>
            </Button>
            <Button
              onPress={async () => {
                if (
                  isSubmitting ||
                  !!editModalErrorSqft ||
                  !editModalSqft ||
                  parseFloat(editModalSqft || '0') > maxTodaySqft
                ) {
                  Alert.alert(t('ERROR'), t('PLEASE_FILL_ALL_INFORMATION'));
                  return false;
                }
                const success = await handleUpdate(
                  editModalSqft,
                  editModalPhotos,
                  editModalUploadResults,
                  editModalComment,
                );
                if (success) {
                  resetAndClose();
                }
              }}
              variant="primary"
              style={[
                styles.button,
                styles.updateButton,
                isSubmitting && styles.buttonFullWidth,
              ]}
            >
              <Text style={styles.textBoldMediumWhite}>
                {isSubmitting
                  ? progressPercentage === 0
                    ? t('SUBMITTING')
                    : t('UPDATING')
                  : t('UPDATE')}
              </Text>
            </Button>
          </View>
        </View>
      </View>
    </Modal>
  );
};

export default EditModal;
