import React, { useCallback } from 'react';
import { ScrollView, View } from 'react-native';
import {
  BaseContainer,
  HeaderBase,
  Text,
  Button,
  BottomSelector,
} from 'tradewize-component';
import type { BottomSelectorOption } from 'tradewize-component';
import { colors } from '../../theme';
import { useAppTranslation } from '../../hooks/useAppTranslation';
import useVerifyMaterialVPO from '../../hooks/useVerifyMaterialVPO';
import { styles } from './styles';
import type { VPOChecklistItem } from '../../types/jobDetail.type';
import { SCREEN_ENUM } from '../../types/global';
import { dispatch } from '../../helper';
import { actionContainer } from '../../../../Auth/src/redux';
import VPOItemCard from './components/VPOItemCard';
import CommentChecklist from '../../components/CommentChecklist';
import { EmptyComponent } from '../../components/EmptyComponent';

// ============================================================================
// Main Screen
// ============================================================================

const VerifyMaterialVPOScreen: React.FC = () => {
  const { t } = useAppTranslation();

  const {
    dataMaterial,
    groupedMaterials,
    isLoading,
    isSubmitting,
    getTypeName,
    submitVPO,
    handleGoBack,
    getInitialValue,
    isSelectorVisible,
    quantityOptions,
    setIsSelectorVisible,
    openQuantitySelector,
    handleSelectQuantity,
  } = useVerifyMaterialVPO();

  const handleQuantityPress = useCallback(
    (itemId: string, maxQuantity: number) => {
      openQuantitySelector(itemId, maxQuantity );
    },
    [openQuantitySelector],
  );

  const handleCommentPress = useCallback((item: VPOChecklistItem) => {
    dispatch(
      actionContainer.showCommentChecklistModal({
        visible: true,
        item: item,
        folderName: 'vpo',
        screenKey: SCREEN_ENUM.VerifyMaterialVPOScreen,
      }),
    );
  }, []);

  const hasData = dataMaterial?.length > 0;

  return (
    <BaseContainer>
      <HeaderBase
        title={t('VERIFY_MATERIAL_VPO')}
        onPressBack={handleGoBack}
        backgroundColor={colors.white}
        colorIconLeft={colors.grayScale100}
        titleStyle={styles.headerTitle}
      />

      {!isLoading && (
        <>
          <ScrollView
            style={styles.container}
            contentContainerStyle={styles.contentContainer}
            showsVerticalScrollIndicator={false}
          >
            {hasData ? (
              Object.entries(groupedMaterials).map(([typeId, items]) => (
                <View key={typeId} style={styles.typeContainer}>
                  {/* Type Header */}
                  <View style={styles.typeHeader}>
                    <View style={styles.typeHeaderContent}>
                      <Text style={styles.typeTitle}>
                        <Text style={styles.typeTitleBold}>
                          {getTypeName(items)}
                        </Text>
                        {'  '}
                        <Text style={styles.typeTitleCount}>
                          ({items.length})
                        </Text>
                      </Text>
                    </View>
                  </View>

                  {/* Items */}
                  <View style={styles.typeItems}>
                    {items.map(item => (
                      <VPOItemCard
                        key={item.id}
                        item={item}
                        onQuantityPress={handleQuantityPress}
                        onCommentPress={handleCommentPress}
                        getInitialValue={getInitialValue}
                        t={t}
                      />
                    ))}
                  </View>
                </View>
              ))
            ) : (
              <EmptyComponent />
            )}
          </ScrollView>

          {/* Submit Button — only show when has data */}
          {hasData && (
            <View style={styles.submitButtonContainer}>
              <Button
                style={[
                  styles.submitButton,
                  isSubmitting && styles.submitButtonDisabled,
                ]}
                onPress={submitVPO}
                disabled={isSubmitting}
              >
                <Text
                  style={[
                    styles.submitButtonText,
                    isSubmitting && styles.submitButtonTextDisabled,
                  ]}
                >
                  {t('VERIFY')}
                </Text>
              </Button>
            </View>
          )}
        </>
      )}

      {/* Quantity Selector Bottom Sheet */}
      {React.useMemo(
        () => (
          <BottomSelector
            title={t('RECEIVED_NUMBER')}
            options={quantityOptions}
            isVisible={isSelectorVisible}
            onClose={() => setIsSelectorVisible(false)}
            onSelect={(option: BottomSelectorOption) =>
              handleSelectQuantity(option)
            }
            containerStyle={styles.selectorContainer}
            enableSearch={true}
          />
        ),
        [
          isSelectorVisible,
          quantityOptions,
          handleSelectQuantity,
          setIsSelectorVisible,
          t,
        ],
      )}
      {/* Comment modal — reuse existing CommentChecklist */}
      <CommentChecklist />
    </BaseContainer>
  );
};

export default VerifyMaterialVPOScreen;
