import React from 'react';
import { View } from 'react-native';
import Svg, { Circle, Defs, LinearGradient, Stop } from 'react-native-svg';
import { Text } from 'tradewize-component';
import { styles } from '../styles';

interface ProgressCircleProps {
  progressPercentage: number;
}

const ProgressCircle = React.memo(
  ({ progressPercentage }: ProgressCircleProps) => {
    return (
      <View style={styles.progressContainer}>
        <View style={styles.progressCircle}>
          <Svg width="200" height="200" style={styles.progressSvg}>
            <Defs>
              <LinearGradient
                id="progressGradient"
                x1="0%"
                y1="0%"
                x2="100%"
                y2="100%"
              >
                <Stop offset="0%" stopColor="#0099FF" stopOpacity="1" />
                <Stop offset="25%" stopColor="#0066FF" stopOpacity="1" />
                <Stop offset="50%" stopColor="#0000FF" stopOpacity="1" />
                <Stop offset="75%" stopColor="#000099" stopOpacity="1" />
                <Stop offset="100%" stopColor="#000066" stopOpacity="1" />
              </LinearGradient>
            </Defs>
            {/* Background circle */}
            <Circle
              cx="100"
              cy="100"
              r="90"
              stroke="#E5E5E5"
              strokeWidth="12"
              fill="transparent"
            />
            {/* Progress circle with gradient */}
            <Circle
              cx="100"
              cy="100"
              r="90"
              stroke="url(#progressGradient)"
              strokeWidth="12"
              fill="transparent"
              strokeDasharray={`${2 * Math.PI * 90}`}
              strokeDashoffset={`${
                2 * Math.PI * 90 * (1 - progressPercentage / 100)
              }`}
              strokeLinecap="round"
              transform="rotate(-90 100 100)"
            />
          </Svg>
          <Text style={styles.progressText}>
            {progressPercentage === 100
              ? '100%'
              : progressPercentage.toFixed(2) + '%'}
          </Text>
        </View>
      </View>
    );
  },
);

export default ProgressCircle;
